export const CANONICAL_TEMPLATE_SOURCES: Record<string, string> = {
  "ccv_a_vista_v2.hbs": "<div class=\"contrato\">\n\n<h1>INSTRUMENTO PARTICULAR DE COMPROMISSO DE VENDA E COMPRA</h1>\n<h2>Modalidade: Pagamento À Vista</h2>\n\n<p style=\"text-align: center; font-size: 24pt; color: #888888;\">❦</p>\n\n<hr>\n\n<h2>QUALIFICAÇÃO DAS PARTES</h2>\n\n<h3>PARTE VENDEDORA</h3>\n\n{{#each vendedores}}\n{{#if (eq this.tipo_pessoa \"fisica\")}}\n<p><strong>Promitente Vendedor(a):</strong></p>\n<p>\nNome: {{this.nome}}<br>\nNacionalidade: {{this.nacionalidade}}<br>\nEstado Civil: {{this.estado_civil}}<br>\nProfissão: {{this.profissao}}<br>\nRG: nº {{this.rg}}<br>\nCPF: nº {{cpf this.cpf}}<br>\n{{#if (existe this.email)}}E-mail: {{this.email}}<br>{{/if}}\n{{#if (existe this.mobile_phone)}}Telefone: {{this.mobile_phone}}<br>{{/if}}\nEndereço: {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}{{#if this.bairro}}, Bairro: {{this.bairro}}{{/if}}, Cidade: {{this.cidade}}-{{this.uf}}, CEP {{cep this.cep}}\n</p>\n\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p><em>(Cônjuge/Companheiro)</em></p>\n<p>\nNome Completo: {{this.conjuge.nome}}<br>\nCPF: {{cpf this.conjuge.cpf}}<br>\nRG: {{this.conjuge.rg}}<br>\nNacionalidade: {{this.conjuge.nacionalidade}}<br>\nProfissão: {{this.conjuge.profissao}}{{#if (existe this.conjuge.email)}}<br>\nE-mail: {{this.conjuge.email}}{{/if}}{{#if (existe this.conjuge.mobile_phone)}}<br>\nTelefone: {{this.conjuge.mobile_phone}}{{/if}}\n</p>\n{{/if}}{{/if}}\n\n{{#if this.tem_procurador}}\n<p><em>Representado(a) por seu(sua) procurador(a):</em></p>\n<p>\nNome: {{this.procurador.nome}}<br>\nCPF: {{cpf this.procurador.cpf}}<br>\nRG: {{this.procurador.rg}}<br>\nEndereço: {{this.procurador.endereco}}, nº {{this.procurador.numero}}, Cidade: {{this.procurador.cidade}}-{{this.procurador.uf}}\n</p>\n{{/if}}\n\n{{else}}\n<p><strong>Promitente Vendedora:</strong></p>\n<p>\nRazão Social: {{this.razao_social}}<br>\nCNPJ: nº {{cnpj this.cnpj}}<br>\nEndereço: {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}{{#if this.bairro}}, Bairro: {{this.bairro}}{{/if}}, Cidade: {{this.cidade}}-{{this.uf}}, CEP {{cep this.cep}}\n</p>\n<p>Neste ato representada por seu(s) representante(s) legal(is):</p>\n<p>\nNome Completo: {{this.representante.nome}}<br>\nCPF: {{cpf this.representante.cpf}}<br>\nNacionalidade: {{this.representante.nacionalidade}}<br>\nEstado Civil: {{this.representante.estado_civil}}<br>\nProfissão: {{this.representante.profissao}}{{#if (existe this.representante.email)}}<br>\nE-mail: {{this.representante.email}}{{/if}}{{#if (existe this.representante.mobile_phone)}}<br>\nTelefone: {{this.representante.mobile_phone}}{{/if}}\n</p>\n{{/if}}\n{{/each}}\n\n<h3>PARTE COMPRADORA</h3>\n\n{{#each compradores}}\n{{#if (eq this.tipo_pessoa \"fisica\")}}\n<p><strong>Promissário(a) Comprador(a):</strong></p>\n<p>\nNome: {{this.nome}}<br>\nNacionalidade: {{this.nacionalidade}}<br>\nEstado Civil: {{this.estado_civil}}<br>\nProfissão: {{this.profissao}}<br>\nRG: nº {{this.rg}}<br>\nCPF: nº {{cpf this.cpf}}<br>\n{{#if (existe this.email)}}E-mail: {{this.email}}<br>{{/if}}\n{{#if (existe this.mobile_phone)}}Telefone: {{this.mobile_phone}}<br>{{/if}}\nEndereço: {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}{{#if this.bairro}}, Bairro: {{this.bairro}}{{/if}}, Cidade: {{this.cidade}}-{{this.uf}}, CEP {{cep this.cep}}\n</p>\n\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p><em>(Cônjuge/Companheiro)</em></p>\n<p>\nNome Completo: {{this.conjuge.nome}}<br>\nCPF: {{cpf this.conjuge.cpf}}<br>\nRG: {{this.conjuge.rg}}<br>\nNacionalidade: {{this.conjuge.nacionalidade}}<br>\nProfissão: {{this.conjuge.profissao}}{{#if (existe this.conjuge.email)}}<br>\nE-mail: {{this.conjuge.email}}{{/if}}{{#if (existe this.conjuge.mobile_phone)}}<br>\nTelefone: {{this.conjuge.mobile_phone}}{{/if}}\n</p>\n{{/if}}{{/if}}\n\n{{#if this.tem_procurador}}\n<p><em>Representado(a) por seu(sua) procurador(a):</em></p>\n<p>\nNome: {{this.procurador.nome}}<br>\nCPF: {{cpf this.procurador.cpf}}<br>\nRG: {{this.procurador.rg}}<br>\nEndereço: {{this.procurador.endereco}}, nº {{this.procurador.numero}}, Cidade: {{this.procurador.cidade}}-{{this.procurador.uf}}\n</p>\n{{/if}}\n\n{{else}}\n<p><strong>Promissária Compradora:</strong></p>\n<p>\nRazão Social: {{this.razao_social}}<br>\nCNPJ: nº {{cnpj this.cnpj}}<br>\nEndereço: {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}{{#if this.bairro}}, Bairro: {{this.bairro}}{{/if}}, Cidade: {{this.cidade}}-{{this.uf}}, CEP {{cep this.cep}}\n</p>\n<p>Neste ato representada por seu(s) representante(s) legal(is):</p>\n<p>\nNome Completo: {{this.representante.nome}}<br>\nCPF: {{cpf this.representante.cpf}}<br>\nNacionalidade: {{this.representante.nacionalidade}}<br>\nEstado Civil: {{this.representante.estado_civil}}<br>\nProfissão: {{this.representante.profissao}}{{#if (existe this.representante.email)}}<br>\nE-mail: {{this.representante.email}}{{/if}}{{#if (existe this.representante.mobile_phone)}}<br>\nTelefone: {{this.representante.mobile_phone}}{{/if}}\n</p>\n{{/if}}\n{{/each}}\n\n<h3>INTERMEDIADORA{{#if comissao.comissionados.length}}{{#if (gt comissao.comissionados.length 1)}}S{{/if}}{{/if}}</h3>\n\n{{#if comissao.comissionados.length}}\n{{#each comissao.comissionados}}\n<p>\n{{#if (eq tipo_pessoa \"fisica\")}}\nCorretor(a): {{nome}}<br>\nCPF: {{cpf cpf}}\n{{else}}\nImobiliária: {{nome}}<br>\nCNPJ: nº {{cnpj cnpj}}\n{{/if}}\n{{#if (existe papel_texto)}}<br>Função: {{papel_texto}}{{/if}}\n{{#if (existe creci)}}<br>CRECI: {{creci}}{{/if}}\n{{#if this.percentual}}<br>Participação: {{this.percentual}}%{{/if}}\n{{#if (existe email)}}<br>E-mail: {{email}}{{/if}}\n{{#if (existe mobile_phone)}}<br>Telefone: {{mobile_phone}}{{/if}}\n</p>\n{{/each}}\n{{else}}\n<p>\n{{#if (eq comissao.corretora_tipo_pessoa \"fisica\")}}\nCorretor(a): {{comissao.imobiliaria_nome}}<br>\nCPF: {{cpf comissao.imobiliaria_cnpj}}<br>\nCRECI: {{comissao.creci}}\n{{else}}\nImobiliária: {{comissao.imobiliaria_nome}}<br>\nCNPJ: nº {{cnpj comissao.imobiliaria_cnpj}}<br>\nCRECI: {{comissao.creci}}\n{{/if}}\n{{#if (existe comissao.imobiliaria_email)}}<br>E-mail: {{comissao.imobiliaria_email}}{{/if}}\n</p>\n{{/if}}\n\n<hr>\n\n<p class=\"doc-intro\">São partes integrantes neste instrumento as pessoas acima qualificadas, doravante denominadas simplesmente <strong>PROMITENTES VENDEDORES</strong> e <strong>PROMISSÁRIOS COMPRADORES</strong>, que, por estarem justos e contratados, celebram o presente <strong>INSTRUMENTO PARTICULAR DE COMPROMISSO DE VENDA E COMPRA</strong>, mediante as cláusulas e condições seguintes:</p>\n\n<hr>\n\n<h2>CLÁUSULA PRIMEIRA - DO OBJETO</h2>\n\n<p><strong>1.1.</strong> Os PROMITENTES VENDEDORES são legítimos proprietários e possuidores do seguinte imóvel:</p>\n\n{{#each imoveis}}\n<p>\nEndereço: {{this.rua}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}, Bairro: {{this.bairro}}, Cidade: {{this.cidade}} - {{this.uf}}, CEP {{cep this.cep}}<br>\nMatrícula: nº {{this.matricula}} do {{this.cartorio}}<br>\nInscrição IPTU: nº {{this.inscricao_iptu}} junto à Prefeitura Municipal{{#if this.inscricao_municipal}}{{#unless (eq this.inscricao_municipal this.inscricao_iptu)}}<br>Inscrição Municipal: nº {{this.inscricao_municipal}}{{/unless}}{{/if}}<br>\n{{#if (existe this.sql)}}SQL: nº {{this.sql}}<br>{{/if}}\nDescrição: {{this.descricao}}\n</p>\n{{/each}}\n\n{{#if (existe config.titulo_aquisitivo)}}\n<p><strong>1.1.1.</strong> O imóvel foi adquirido pelos PROMITENTES VENDEDORES conforme {{config.titulo_aquisitivo}}{{#if (existe config.registro_aquisitivo)}}, registrado sob {{config.registro_aquisitivo}}{{/if}} na matrícula supramencionada.</p>\n{{/if}}\n\n{{#if (existe observacao_imovel)}}\n<p><strong>1.2.</strong> {{observacao_imovel}}</p>\n{{/if}}\n\n<!-- CLAUSE_SLOT:G1 -->\n\n<hr>\n\n<h2>CLÁUSULA SEGUNDA - DO PREÇO</h2>\n\n<p><strong>2.1.</strong> O preço certo e ajustado para a presente transação é de {{moeda pagamento.valor_total}} ({{extenso pagamento.valor_total}}), que será pago da seguinte forma:</p>\n\n{{#if (gt pagamento.sinal_arras 0)}}\n<p><strong>a)</strong> A título de sinal e princípio de pagamento (arras confirmatórias), o valor de {{moeda pagamento.sinal_arras}} ({{extenso pagamento.sinal_arras}}), a ser pago em até 1 (um) dia útil contado da assinatura do presente instrumento, mediante transferência bancária (TED/PIX) nas contas indicadas pelos PROMITENTES VENDEDORES.</p>\n{{/if}}\n\n{{#if pagamento.parcelas.length}}\n{{#each pagamento.parcelas}}\n<p><strong>{{this.letra}})</strong> {{this.tipo_texto}}: {{moeda this.valor}} ({{extenso this.valor}}), {{#if (existe this.momento_data_texto)}}até {{this.momento_data_texto}}{{else}}em {{numero this.dias}} ({{numeroExtenso this.dias}}) dia(s) corridos {{#if (existe this.momento_texto)}}{{this.momento_texto}}{{else}}contados da assinatura deste instrumento{{/if}}{{/if}}, {{#if (existe this.meio_pagamento_texto)}}{{this.meio_pagamento_texto}}{{else}}mediante transferência bancária (TED ou PIX){{/if}}{{#if (existe this.destino_texto)}}, {{this.destino_texto}}{{else}} nas contas indicadas pelos PROMITENTES VENDEDORES{{/if}}.</p>\n{{/each}}\n{{else}}\n<p><strong>b)</strong> O saldo remanescente de {{moeda pagamento.recursos_proprios}} ({{extenso pagamento.recursos_proprios}}), a título de recursos próprios, a ser pago à vista mediante transferência bancária (TED/PIX) nas contas indicadas pelos PROMITENTES VENDEDORES.</p>\n{{/if}}\n\n{{#if (gt pagamento.sinal_arras 0)}}\n<p><strong>2.1.{{subnum \"2.1\"}}.</strong> Caso o sinal estipulado na alínea \"a\" não seja efetivamente creditado na conta dos PROMITENTES VENDEDORES no prazo de 1 (um) dia útil contado da assinatura deste instrumento, operar-se-á a rescisão automática do presente contrato, sem qualquer ônus para quaisquer das partes, retornando-se ao <em>status quo ante</em>.</p>\n{{/if}}\n\n<p><strong>2.1.{{subnum \"2.1\"}}.</strong> Todos os pagamentos deverão ser realizados exclusivamente nas contas bancárias indicadas por escrito pelos PROMITENTES VENDEDORES, servindo os comprovantes de transferência como recibos de quitação parcial ou total.</p>\n\n{{#if (existe config.saldo_devedor_vendedor)}}\n<p><strong>2.1.{{subnum \"2.1\"}}.</strong> Os PROMITENTES VENDEDORES declaram que sobre o imóvel objeto deste instrumento incide saldo devedor de alienação fiduciária em favor de instituição financeira, no montante aproximado de {{moeda config.saldo_devedor_vendedor}} ({{extenso config.saldo_devedor_vendedor}}), obrigando-se a promover a sua quitação e a respectiva baixa do gravame na matrícula do imóvel, em prazo compatível com a entrega da posse e a lavratura da escritura definitiva, sob pena de rescisão por culpa dos PROMITENTES VENDEDORES.</p>\n{{/if}}\n\n{{#if (existe config.permuta_descricao)}}\n<p><strong>2.1.{{subnum \"2.1\"}}.</strong> Parte do preço estipulado nesta cláusula é satisfeita mediante permuta nos seguintes termos: {{config.permuta_descricao}}. A entrega efetiva do(s) bem(ns) permutado(s), com a documentação regularizada e livre de quaisquer ônus, é condição para a quitação parcial correspondente.</p>\n{{/if}}\n\n<!-- CLAUSE_SLOT:G1 -->\n\n<hr>\n\n<h2>CLÁUSULA TERCEIRA - DA IMISSÃO NA POSSE</h2>\n\n<p><strong>3.1.</strong> A posse direta do imóvel será transmitida aos PROMISSÁRIOS COMPRADORES {{#if (existe entrega_posse.momento_texto)}}{{entrega_posse.momento_texto}}{{else}}em até {{config.prazo_posse_dias}} ({{numeroExtenso config.prazo_posse_dias}}) dias corridos contados do pagamento integral do preço estipulado na Cláusula Segunda{{/if}}, livre e desembaraçada de pessoas e coisas.</p>\n\n<p><strong>3.1.1.</strong> O atraso injustificado na entrega da posse por parte dos PROMITENTES VENDEDORES acarretará multa diária de {{moeda config.multa_diaria_posse}} ({{extenso config.multa_diaria_posse}}), sem prejuízo das demais cominações legais. Após 30 (trinta) dias de atraso, a multa diária será acrescida de 20% (vinte por cento) sobre o seu valor.</p>\n\n<p><strong>3.2.</strong> O imóvel será entregue no estado em que se encontra, tendo os PROMISSÁRIOS COMPRADORES vistoriado e aceito o bem na modalidade <em>ad corpus</em>, não cabendo reclamação posterior quanto às suas dimensões e características.{{#if (or (eq config.vicios_opcao \"renuncia\") (eq config.vicios_opcao \"detalhado\") (eq config.vicios_opcao \"reparar\") (eq config.vicios_opcao \"desocultados\"))}} A responsabilidade por vícios e pelo estado de conservação do imóvel rege-se pela cláusula 10.4 deste instrumento.{{else}} Quanto ao estado de conservação, os PROMISSÁRIOS COMPRADORES aceitam o imóvel conforme vistoriado, ressalvados os vícios ocultos não detectáveis em vistoria normal, nos termos dos arts. 441 a 446 do Código Civil.{{/if}}</p>\n\n{{#if (existe config.locacao_situacao)}}\n{{#if (eq config.locacao_situacao \"vendedor-entregara\")}}\n<p><strong>3.3.</strong> O imóvel encontra-se atualmente ocupado por terceiro em contrato de locação. Os PROMITENTES VENDEDORES comprometem-se a entregá-lo desocupado{{#if (existe config.locacao_data)}}, até {{config.locacao_data}}{{/if}}, livre de quaisquer ocupantes e de seus pertences, sob pena de rescisão por culpa dos PROMITENTES VENDEDORES.</p>\n{{else}}\n<p><strong>3.3.</strong> O imóvel encontra-se atualmente ocupado por terceiro em contrato de locação{{#if (existe config.locacao_data)}}, com vigência prevista até {{config.locacao_data}}{{/if}}. Os PROMISSÁRIOS COMPRADORES declaram ciência e concordância em manter o contrato de locação vigente, sub-rogando-se nos direitos e obrigações do locador a partir da imissão na posse.</p>\n{{/if}}\n{{/if}}\n\n{{#if (existe config.itens_entrega)}}\n<p><strong>3.4.</strong> Acompanham o imóvel e estão inclusos no preço total estipulado na Cláusula Segunda os seguintes itens, benfeitorias e acessórios: {{config.itens_entrega}}. Os PROMISSÁRIOS COMPRADORES declaram tê-los vistoriado e os aceitam no estado em que se encontram.</p>\n{{/if}}\n\n<!-- CLAUSE_SLOT:G2 -->\n\n<hr>\n\n<h2>CLÁUSULA QUARTA - DA ESCRITURA PÚBLICA</h2>\n\n<p><strong>4.1.</strong> As partes se comprometem a lavrar a Escritura Pública de Compra e Venda no prazo de {{config.prazo_escritura_dias}} ({{numeroExtenso config.prazo_escritura_dias}}) dias corridos, contados da assinatura do presente instrumento ou do pagamento integral do preço, o que ocorrer por último.</p>\n\n<p><strong>4.2.</strong> Todas as despesas relativas à transferência da propriedade, incluindo ITBI (Imposto sobre Transmissão de Bens Imóveis), FRJ (Fundo de Reaparelhamento da Justiça), emolumentos cartorários e demais custas, serão de exclusiva responsabilidade dos PROMISSÁRIOS COMPRADORES.</p>\n\n<p><strong>4.3.</strong> O atraso doloso de qualquer das partes na lavratura da escritura pública acarretará multa diária de {{moeda config.multa_diaria_escritura}} ({{extenso config.multa_diaria_escritura}}), sem prejuízo das demais cominações contratuais e legais.</p>\n\n<p><strong>4.4.</strong> Fica assegurado aos PROMISSÁRIOS COMPRADORES o direito de adjudicação compulsória do imóvel, nos termos do artigo 1.418 do Código Civil, caso os PROMITENTES VENDEDORES se recusem injustificadamente a outorgar a escritura definitiva.</p>\n\n<hr>\n\n<h2>CLÁUSULA QUINTA - DOS TRIBUTOS E ENCARGOS</h2>\n\n<p><strong>5.1.</strong> Todos os tributos, taxas, contribuições condominiais e demais encargos incidentes sobre o imóvel serão de responsabilidade dos PROMITENTES VENDEDORES até a data da efetiva entrega das chaves e imissão na posse dos PROMISSÁRIOS COMPRADORES, passando a ser de responsabilidade destes a partir de então.</p>\n\n<p><strong>5.1.1.</strong> Os PROMISSÁRIOS COMPRADORES deverão providenciar a transferência de titularidade das contas de consumo (água, energia elétrica, gás) e demais cadastros perante a Prefeitura Municipal e administradora condominial no prazo de 30 (trinta) dias contados da imissão na posse.</p>\n\n{{#if (eq config.tem_debitos true)}}\n<p><strong>5.2.</strong> Os PROMITENTES VENDEDORES declaram a existência dos seguintes débitos pendentes sobre o imóvel, cuja quitação será de sua exclusiva responsabilidade{{#if (existe config.debitos_assumidos_descricao)}}, ressalvada a exceção da Cláusula 5.3{{/if}}, devendo ser comprovada antes da lavratura da escritura definitiva:</p>\n<ul>\n{{#if (existe config.debito_iptu_valor)}}<li>IPTU em atraso: {{moeda config.debito_iptu_valor}} ({{extenso config.debito_iptu_valor}});</li>{{/if}}\n{{#if (existe config.debito_condominio_valor)}}<li>Despesas condominiais em atraso: {{moeda config.debito_condominio_valor}} ({{extenso config.debito_condominio_valor}});</li>{{/if}}\n{{#if (existe config.debito_outros_descricao)}}<li>Outros débitos: {{config.debito_outros_descricao}}.</li>{{/if}}\n</ul>\n{{/if}}\n\n{{#if (existe config.debitos_assumidos_descricao)}}\n<p><strong>5.3.</strong> Em derrogação parcial às cláusulas anteriores, os PROMISSÁRIOS COMPRADORES assumem expressamente, com pleno conhecimento de causa, o pagamento dos seguintes débitos: {{config.debitos_assumidos_descricao}}. O valor assumido foi considerado na composição do preço pactuado na Cláusula Segunda.</p>\n{{/if}}\n\n{{#if (existe config.regularizacoes_descricao)}}\n<p><strong>5.4.</strong> Os PROMITENTES VENDEDORES comprometem-se a promover, às suas exclusivas expensas, as seguintes regularizações pendentes: {{config.regularizacoes_descricao}}. O prazo para conclusão é de {{#if (existe config.regularizacoes_prazo_dias)}}{{numero config.regularizacoes_prazo_dias}} ({{numeroExtenso config.regularizacoes_prazo_dias}}){{else}}30 (trinta){{/if}} dias corridos contados da assinatura deste instrumento, sob pena de retenção, pelos PROMISSÁRIOS COMPRADORES, do saldo do preço até a efetiva regularização.</p>\n{{/if}}\n\n<hr>\n\n<h2>CLÁUSULA SEXTA - DA DOCUMENTAÇÃO</h2>\n\n<p><strong>6.1.</strong> Os PROMITENTES VENDEDORES se obrigam a entregar aos PROMISSÁRIOS COMPRADORES, no prazo de 7 (sete) dias corridos contados da assinatura do presente instrumento, a seguinte documentação:</p>\n\n<p><strong>a) Do imóvel:</strong></p>\n<ul>\n<li>Certidão de matrícula atualizada (emitida há no máximo 30 dias);</li>\n<li>Certidão Negativa de Débitos de IPTU;</li>\n<li>Declaração de quitação condominial (se aplicável);</li>\n<li>Certidões negativas de concessionárias (água, energia, gás).</li>\n</ul>\n\n<p><strong>b) Pessoais dos vendedores:</strong></p>\n<ul>\n<li>Cópias de RG e CPF;</li>\n<li>Certidão de estado civil atualizada;</li>\n<li>Consulta ao CENPROT (Central Nacional de Protesto);</li>\n<li>Certidões dos distribuidores cíveis e criminais da Justiça Estadual e Federal;</li>\n<li>Certidão de feitos da Justiça do Trabalho;</li>\n<li>Certidão Negativa de Débitos Federais.</li>\n</ul>\n\n<p><strong>6.2.</strong> Na hipótese de constar certidão positiva em nome dos PROMITENTES VENDEDORES, estes deverão apresentar esclarecimentos detalhados e demonstrar que seu patrimônio residual é suficiente para fazer frente às obrigações, sob pena de rescisão justificada pelos PROMISSÁRIOS COMPRADORES.</p>\n\n<p><strong>6.3.</strong> O atraso na entrega da documentação por parte dos PROMITENTES VENDEDORES autorizará os PROMISSÁRIOS COMPRADORES a suspenderem quaisquer pagamentos pendentes pelo prazo de até 15 (quinze) dias, sem configuração de mora, até a regularização documental.</p>\n\n<p><strong>6.4.</strong> As certidões deverão ser obtidas tanto na comarca de situação do imóvel quanto na comarca de residência dos PROMITENTES VENDEDORES, quando diversas.</p>\n\n<hr>\n\n<h2>CLÁUSULA SÉTIMA - DA IRREVOGABILIDADE E IRRETRATABILIDADE</h2>\n\n<p><strong>7.1.</strong> O presente instrumento é celebrado em caráter irrevogável e irretratável, obrigando as partes, seus herdeiros e sucessores, renunciando expressamente à faculdade de arrependimento prevista no artigo 420 do Código Civil.</p>\n\n<hr>\n\n<h2>CLÁUSULA OITAVA - DA INADIMPLÊNCIA</h2>\n\n<p><strong>8.1.</strong> O inadimplemento de qualquer obrigação pecuniária prevista neste contrato sujeitará a parte infratora ao pagamento de:</p>\n<ul>\n<li>Multa moratória de {{numero config.multa_penal_moratoria}}% ({{numeroExtenso config.multa_penal_moratoria}} por cento) sobre o {{config.base_calculo_multa}};</li>\n<li>Juros moratórios de {{numero config.juros_mensais_atraso}}% ({{numeroExtenso config.juros_mensais_atraso}} por cento) ao mês, calculados <em>pro rata die</em>;</li>\n<li>Correção monetária pelo {{config.atualizacao_monetaria}} desde a data do vencimento.</li>\n</ul>\n\n<p><strong>8.1.1.</strong> Transcorrido o prazo de {{numero config.prazo_atraso_rescisao}} ({{numeroExtenso config.prazo_atraso_rescisao}}) dias sem a purgação da mora, a parte credora poderá optar pela rescisão contratual, nos termos da Cláusula Nona, ou pela execução forçada das obrigações.</p>\n\n<!-- CLAUSE_SLOT:G3 -->\n\n<hr>\n\n<h2>CLÁUSULA NONA - DA RESCISÃO</h2>\n\n<p><strong>9.1.</strong> Configurada a inadimplência nos termos da Cláusula Oitava, a parte inadimplente terá o prazo adicional de {{numero config.prazo_atraso_rescisao}} ({{numeroExtenso config.prazo_atraso_rescisao}}) dias para purgação da mora, contados da notificação extrajudicial enviada pela parte credora.</p>\n\n<p><strong>9.2.</strong> Na hipótese de rescisão por culpa dos PROMISSÁRIOS COMPRADORES, os PROMITENTES VENDEDORES reterão {{numero config.multa_penal_compensatoria}}% ({{numeroExtenso config.multa_penal_compensatoria}} por cento) do valor total do contrato a título de perdas e danos pré-fixadas, devolvendo o saldo remanescente em até {{numero config.prazo_multa_rescisoria}} ({{numeroExtenso config.prazo_multa_rescisoria}}) dias.</p>\n\n<p><strong>9.3.</strong> Na hipótese de rescisão por culpa dos PROMITENTES VENDEDORES, estes deverão devolver integralmente todos os valores recebidos, acrescidos de {{numero config.multa_penal_compensatoria}}% ({{numeroExtenso config.multa_penal_compensatoria}} por cento) do valor total do contrato a título de perdas e danos pré-fixadas, no prazo de {{numero config.prazo_multa_rescisoria}} ({{numeroExtenso config.prazo_multa_rescisoria}}) dias.</p>\n\n<p><strong>9.4.</strong> O atraso na devolução dos valores devidos por força de rescisão contratual acarretará multa diária de {{moeda config.multa_cominatoria_diaria}} ({{extenso config.multa_cominatoria_diaria}}), além dos encargos moratórios previstos na Cláusula Oitava.</p>\n\n{{#if (eq config.desistencia_permite true)}}\n<p><strong>9.5.</strong> Fica facultado aos PROMISSÁRIOS COMPRADORES, no prazo de {{#if (existe config.desistencia_prazo_dias)}}{{numero config.desistencia_prazo_dias}} ({{numeroExtenso config.desistencia_prazo_dias}}){{else}}7 (sete){{/if}} dias corridos contados da assinatura deste instrumento, o direito de desistência sem qualquer penalidade, mediante notificação escrita aos PROMITENTES VENDEDORES e restituição integral dos valores eventualmente pagos no prazo de 5 (cinco) dias úteis contados da notificação.</p>\n{{/if}}\n\n<!-- CLAUSE_SLOT:G3 -->\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA - DAS DECLARAÇÕES</h2>\n\n<p><strong>10.1.</strong> Os PROMITENTES VENDEDORES declaram, sob as penas da lei:</p>\n<ul>\n<li>Que o imóvel objeto deste contrato encontra-se livre e desembaraçado de quaisquer ônus reais, gravames, penhoras, arrestos, sequestros, usufrutos, servidões ou quaisquer outros impedimentos;</li>\n<li>Que não existem ações reais ou pessoais reipersecutórias que possam afetar o imóvel ou os direitos dos PROMISSÁRIOS COMPRADORES;</li>\n<li>Que respondem integralmente pela evicção, nos termos dos artigos 447 a 457 do Código Civil;</li>\n<li>Que a presente alienação não os reduz à insolvência, possuindo patrimônio suficiente para fazer frente a eventuais obrigações, inclusive de natureza societária.</li>\n</ul>\n\n<p><strong>10.2.</strong> As partes declaram ter lido integralmente o presente contrato, estando cientes de todos os seus termos e condições, firmando-o de livre e espontânea vontade, nos termos do artigo 54 da Lei nº 13.097/2015.</p>\n\n<p><strong>10.3.</strong> A presente venda é realizada na modalidade <em>ad corpus</em>, sendo meramente enunciativas as referências a medidas e confrontações do imóvel, prevalecendo a área existente sobre a área mencionada em eventual descrição.</p>\n\n{{#if (existe config.vicios_opcao)}}\n{{#if (eq config.vicios_opcao \"renuncia\")}}\n<p><strong>10.4.</strong> Os PROMISSÁRIOS COMPRADORES declaram ter vistoriado o imóvel no estado em que se encontra e o aceitam como tal, renunciando expressamente ao direito de pleitear qualquer indenização, abatimento de preço ou rescisão em razão de vícios redibitórios aparentes, ressalvada a hipótese de vícios ocultos não detectáveis em vistoria normal e dos quais os PROMITENTES VENDEDORES tinham ciência prévia, hipótese em que respondem pela evicção nos termos dos arts. 441 a 446 do Código Civil.</p>\n{{else}}\n{{#if (eq config.vicios_opcao \"detalhado\")}}\n<p><strong>10.4.</strong> Os PROMITENTES VENDEDORES declaram, sob as penas da lei, que o imóvel se encontra livre de vícios construtivos, redibitórios ou ocultos, responsabilizando-se nos termos dos arts. 441 a 446 do Código Civil pelos vícios eventualmente descobertos pelos PROMISSÁRIOS COMPRADORES no prazo legal.</p>\n{{else}}\n{{#if (eq config.vicios_opcao \"reparar\")}}\n<p><strong>10.4.</strong> Os PROMITENTES VENDEDORES comprometem-se a realizar, às suas exclusivas expensas, os seguintes reparos antes da entrega da posse: {{config.vicios_descricao}}. A não execução tempestiva e adequada dos reparos autoriza os PROMISSÁRIOS COMPRADORES a executá-los e descontar o respectivo valor do saldo do preço, ou a rescindir o contrato sem ônus, com restituição integral dos valores pagos.</p>\n{{else}}\n{{#if (eq config.vicios_opcao \"desocultados\")}}\n<p><strong>10.4.</strong> Os PROMITENTES VENDEDORES declaram, com expressa ciência e concordância dos PROMISSÁRIOS COMPRADORES, a existência dos seguintes vícios construtivos ou ocultos no imóvel: {{config.vicios_descricao}}. Os PROMISSÁRIOS COMPRADORES, cientes destes vícios, renunciam ao direito de pleitear sua reparação, indenização ou abatimento de preço com fundamento nos vícios ora declarados.</p>\n{{/if}}\n{{/if}}\n{{/if}}\n{{/if}}\n{{/if}}\n\n<!-- CLAUSE_SLOT:G6 -->\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA PRIMEIRA - DA COMISSÃO</h2>\n\n{{#if (gt comissao.comissionados.length 1)}}\n<p><strong>11.1.</strong> A comissão total de corretagem desta transação é de {{moeda comissao.valor}} ({{extenso comissao.valor}}), correspondente a {{percentual comissao.valor pagamento.valor_total}} do valor total da transação, a ser paga pela {{#if (existe comissao.quem_paga_texto)}}{{comissao.quem_paga_texto}}{{else}}Parte Compradora{{/if}}{{#if (existe comissao.quando_paga_texto)}} {{comissao.quando_paga_texto}}{{/if}}, distribuída entre os comissionados conforme abaixo:</p>\n<ul>\n{{#each comissao.comissionados}}\n<li>{{#if (eq tipo_pessoa \"fisica\")}}ao(à) corretor(a) {{nome}}, inscrito(a) no CPF nº {{cpf cpf}}{{else}}à imobiliária {{nome}}, inscrita no CNPJ nº {{cnpj cnpj}}{{/if}}{{#if (existe creci)}}, CRECI nº {{creci}}{{/if}}{{#if (existe papel_texto)}} ({{papel_texto}}){{/if}} — {{#if this.percentual}}{{this.percentual}}% = {{/if}}{{moeda valor}} ({{extenso valor}}).</li>\n{{/each}}\n</ul>\n{{else}}\n<p><strong>11.1.</strong> A comissão de intermediação imobiliária devida à INTERMEDIADORA{{#if (existe comissao.imobiliaria_nome)}}, {{comissao.imobiliaria_nome}}, {{#if (eq comissao.corretora_tipo_pessoa \"fisica\")}}inscrito(a) no CPF nº {{cpf comissao.imobiliaria_cnpj}}{{else}}inscrita no CNPJ nº {{cnpj comissao.imobiliaria_cnpj}}{{/if}}{{#if (existe comissao.creci)}}, CRECI nº {{comissao.creci}}{{/if}},{{/if}} é de {{moeda comissao.valor}} ({{extenso comissao.valor}}), correspondente a {{percentual comissao.valor pagamento.valor_total}} do valor total da transação, a ser paga{{#if (existe comissao.quem_paga_texto)}} pela {{comissao.quem_paga_texto}}{{/if}}{{#if (existe comissao.quando_paga_texto)}} {{comissao.quando_paga_texto}}{{/if}}.</p>\n{{/if}}\n\n<p><strong>11.2.</strong> Em caso de rescisão contratual, a responsabilidade pelo pagamento da comissão será de quem der causa ao desfazimento do negócio, nos termos do artigo 723 do Código Civil.</p>\n\n<p><strong>11.3.</strong> O atraso no pagamento da comissão sujeitará o devedor ao pagamento de multa de {{numero config.multa_penal_moratoria}}% ({{numeroExtenso config.multa_penal_moratoria}} por cento) sobre o valor devido, acrescida de correção monetária pelo {{config.atualizacao_monetaria}} e juros moratórios de {{numero config.juros_mensais_atraso}}% ({{numeroExtenso config.juros_mensais_atraso}} por cento) ao mês.</p>\n\n<p><strong>11.4.</strong> A responsabilidade da INTERMEDIADORA limita-se exclusivamente à intermediação do negócio, não respondendo por obrigações assumidas pelas partes neste instrumento.</p>\n\n<!-- CLAUSE_SLOT:G5 -->\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA SEGUNDA - DA LGPD</h2>\n\n<p><strong>12.1.</strong> As partes declaram ciência e concordância com o tratamento de seus dados pessoais para fins de execução do presente contrato, em conformidade com a Lei nº 13.709/2018 (Lei Geral de Proteção de Dados Pessoais), observados os princípios estabelecidos em seu artigo 6º, especialmente os de finalidade, adequação, necessidade, livre acesso, qualidade dos dados, transparência, segurança, prevenção e não discriminação.</p>\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA TERCEIRA - DAS COMUNICAÇÕES</h2>\n\n<p><strong>13.1.</strong> Todas as comunicações, notificações e interpelações entre as partes deverão ser realizadas por escrito, sendo considerados válidos os seguintes meios: e-mail, aplicativo de mensagens instantâneas (WhatsApp) e notificação judicial ou extrajudicial, sempre direcionados aos endereços e contatos informados na qualificação das partes.</p>\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA QUARTA - DA CONTRATAÇÃO ELETRÔNICA</h2>\n\n<p><strong>14.1.</strong> O presente instrumento particular, firmado por meio eletrônico, constitui título executivo extrajudicial para todos os fins de direito, nos termos da Medida Provisória nº 2.200-2/2001, que instituiu a Infraestrutura de Chaves Públicas Brasileira (ICP-Brasil), e do artigo 784, inciso III, do Código de Processo Civil.</p>\n\n<p><strong>14.2.</strong> As partes reconhecem que este contrato será considerado assinado e vinculante após a aposição de assinatura eletrônica por todas as partes envolvidas, produzindo todos os seus efeitos legais a partir de então.</p>\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA QUINTA - DO FORO</h2>\n\n{{#if (eq foro \"arbitragem\")}}\n<p><strong>15.1.</strong> Para dirimir eventuais disputas e controvérsias envolvendo o presente instrumento, as partes expressamente elegem, por convenção de arbitragem e exclusão de qualquer outro foro, nos termos do artigo 5º e do §1º do artigo 4º da Lei nº 9.307/1996, os seguintes foros privados:</p>\n\n<ul>\n  <li>TASP (Centro de Mediação e Arbitragem de São Paulo) — https://www.arbitragem.com.br/</li>\n  <li>ACORDIA — https://acordia.com.br/</li>\n</ul>\n\n<p><strong>15.2.</strong> Fica acordado que a parte interessada em submeter a controvérsia à arbitragem poderá escolher livremente entre as câmaras arbitrais elencadas acima, respeitando-se o regulamento interno da câmara escolhida, cujos custos serão suportados pela parte requerente, salvo disposição diversa no laudo arbitral.</p>\n{{else}}\n<p><strong>15.1.</strong> Para dirimir quaisquer dúvidas ou controvérsias oriundas do presente contrato, as partes elegem o foro da situação do imóvel, com exclusão de qualquer outro, por mais privilegiado que seja.</p>\n{{/if}}\n\n<hr>\n\n<p>E por estarem assim justos e contratados, firmam o presente instrumento em meio eletrônico.</p>\n\n<p>{{config.municipio_imovel}}{{#if (existe config.data_assinatura)}}, {{dataExtenso config.data_assinatura}}{{/if}}.</p>\n\n<div class=\"assinaturas\">\n\n<h3>PROMITENTES VENDEDORES</h3>\n{{#each vendedores}}\n<p>\n_______________________________<br>\n{{this.nome}}<br>\n{{#if (eq this.tipo_pessoa \"fisica\")}}\nCPF: {{cpf this.cpf}}\n{{else}}\nCNPJ: {{cnpj this.cnpj}}<br>\nRepresentante: {{this.representante.nome}}\n{{/if}}\n</p>\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p>\n_______________________________<br>\n{{this.conjuge.nome}}<br>\nCPF: {{cpf this.conjuge.cpf}}<br>\n(Cônjuge/Companheiro(a))\n</p>\n{{/if}}{{/if}}\n{{/each}}\n\n<h3>PROMISSÁRIOS COMPRADORES</h3>\n{{#each compradores}}\n<p>\n_______________________________<br>\n{{this.nome}}<br>\n{{#if (eq this.tipo_pessoa \"fisica\")}}\nCPF: {{cpf this.cpf}}\n{{else}}\nCNPJ: {{cnpj this.cnpj}}<br>\nRepresentante: {{this.representante.nome}}\n{{/if}}\n</p>\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p>\n_______________________________<br>\n{{this.conjuge.nome}}<br>\nCPF: {{cpf this.conjuge.cpf}}<br>\n(Cônjuge/Companheiro(a))\n</p>\n{{/if}}{{/if}}\n{{/each}}\n\n<h3>INTERMEDIADORA{{#if comissao.comissionados.length}}{{#if (gt comissao.comissionados.length 1)}}S{{/if}}{{/if}}</h3>\n{{#if comissao.comissionados.length}}\n{{#each comissao.comissionados}}\n{{#unless (eq incluir_como_signatario false)}}\n<p>\n_______________________________<br>\n{{nome}}<br>\n{{#if (eq tipo_pessoa \"fisica\")}}CPF: {{cpf cpf}}{{else}}CNPJ: {{cnpj cnpj}}{{/if}}{{#if (existe creci)}}<br>\nCRECI: {{creci}}{{/if}}\n</p>\n{{/unless}}\n{{/each}}\n{{else}}\n<p>\n_______________________________<br>\n{{comissao.imobiliaria_nome}}<br>\n{{#if (eq comissao.corretora_tipo_pessoa \"fisica\")}}CPF: {{cpf comissao.imobiliaria_cnpj}}{{else}}CNPJ: {{cnpj comissao.imobiliaria_cnpj}}{{/if}}{{#if (existe comissao.creci)}}<br>\nCRECI: {{comissao.creci}}{{/if}}\n</p>\n{{/if}}\n\n<h3>TESTEMUNHAS</h3>\n{{#each testemunhas}}\n<p>_______________________________<br>Nome: {{#if this.nome}}{{this.nome}}{{else}}___________________________{{/if}}<br>CPF: {{#if this.cpf}}{{cpf this.cpf}}{{else}}___________________________{{/if}}</p>\n{{/each}}\n\n</div>\n\n</div>\n",
  "ccv_financiamento_v2.hbs": "<div class=\"contrato\">\n\n<h1>INSTRUMENTO PARTICULAR DE COMPROMISSO DE VENDA E COMPRA</h1>\n<h2>Modalidade: Financiamento Imobiliário</h2>\n\n<p style=\"text-align: center; font-size: 24pt; color: #888888;\">❦</p>\n\n<hr>\n\n<h2>QUALIFICAÇÃO DAS PARTES</h2>\n\n<h3>PARTE VENDEDORA</h3>\n\n{{#each vendedores}}\n{{#if (eq this.tipo_pessoa \"fisica\")}}\n<p><strong>Promitente Vendedor(a):</strong></p>\n<p>\nNome: {{this.nome}}<br>\nNacionalidade: {{this.nacionalidade}}<br>\nEstado Civil: {{this.estado_civil}}<br>\nProfissão: {{this.profissao}}<br>\nRG: nº {{this.rg}}<br>\nCPF: nº {{cpf this.cpf}}<br>\n{{#if (existe this.email)}}E-mail: {{this.email}}<br>{{/if}}\n{{#if (existe this.mobile_phone)}}Telefone: {{this.mobile_phone}}<br>{{/if}}\nEndereço: {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}{{#if this.bairro}}, Bairro: {{this.bairro}}{{/if}}, Cidade: {{this.cidade}}-{{this.uf}}, CEP {{cep this.cep}}\n</p>\n\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p><em>(Cônjuge/Companheiro)</em></p>\n<p>\nNome Completo: {{this.conjuge.nome}}<br>\nCPF: {{cpf this.conjuge.cpf}}<br>\nRG: {{this.conjuge.rg}}<br>\nNacionalidade: {{this.conjuge.nacionalidade}}<br>\nProfissão: {{this.conjuge.profissao}}{{#if (existe this.conjuge.email)}}<br>\nE-mail: {{this.conjuge.email}}{{/if}}{{#if (existe this.conjuge.mobile_phone)}}<br>\nTelefone: {{this.conjuge.mobile_phone}}{{/if}}\n</p>\n{{/if}}{{/if}}\n\n{{#if this.tem_procurador}}\n<p><em>Representado(a) por seu(sua) procurador(a):</em></p>\n<p>\nNome: {{this.procurador.nome}}<br>\nCPF: {{cpf this.procurador.cpf}}<br>\nRG: {{this.procurador.rg}}<br>\nEndereço: {{this.procurador.endereco}}, nº {{this.procurador.numero}}, Cidade: {{this.procurador.cidade}}-{{this.procurador.uf}}\n</p>\n{{/if}}\n\n{{else}}\n<p><strong>Promitente Vendedora:</strong></p>\n<p>\nRazão Social: {{this.razao_social}}<br>\nCNPJ: nº {{cnpj this.cnpj}}<br>\nEndereço: {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}{{#if this.bairro}}, Bairro: {{this.bairro}}{{/if}}, Cidade: {{this.cidade}}-{{this.uf}}, CEP {{cep this.cep}}\n</p>\n<p>Neste ato representada por seu(s) representante(s) legal(is):</p>\n<p>\nNome Completo: {{this.representante.nome}}<br>\nCPF: {{cpf this.representante.cpf}}<br>\nNacionalidade: {{this.representante.nacionalidade}}<br>\nEstado Civil: {{this.representante.estado_civil}}<br>\nProfissão: {{this.representante.profissao}}{{#if (existe this.representante.email)}}<br>\nE-mail: {{this.representante.email}}{{/if}}{{#if (existe this.representante.mobile_phone)}}<br>\nTelefone: {{this.representante.mobile_phone}}{{/if}}\n</p>\n{{/if}}\n{{/each}}\n\n<h3>PARTE COMPRADORA</h3>\n\n{{#each compradores}}\n{{#if (eq this.tipo_pessoa \"fisica\")}}\n<p><strong>Promissário(a) Comprador(a):</strong></p>\n<p>\nNome: {{this.nome}}<br>\nNacionalidade: {{this.nacionalidade}}<br>\nEstado Civil: {{this.estado_civil}}<br>\nProfissão: {{this.profissao}}<br>\nRG: nº {{this.rg}}<br>\nCPF: nº {{cpf this.cpf}}<br>\n{{#if (existe this.email)}}E-mail: {{this.email}}<br>{{/if}}\n{{#if (existe this.mobile_phone)}}Telefone: {{this.mobile_phone}}<br>{{/if}}\nEndereço: {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}{{#if this.bairro}}, Bairro: {{this.bairro}}{{/if}}, Cidade: {{this.cidade}}-{{this.uf}}, CEP {{cep this.cep}}\n</p>\n\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p><em>(Cônjuge/Companheiro)</em></p>\n<p>\nNome Completo: {{this.conjuge.nome}}<br>\nCPF: {{cpf this.conjuge.cpf}}<br>\nRG: {{this.conjuge.rg}}<br>\nNacionalidade: {{this.conjuge.nacionalidade}}<br>\nProfissão: {{this.conjuge.profissao}}{{#if (existe this.conjuge.email)}}<br>\nE-mail: {{this.conjuge.email}}{{/if}}{{#if (existe this.conjuge.mobile_phone)}}<br>\nTelefone: {{this.conjuge.mobile_phone}}{{/if}}\n</p>\n{{/if}}{{/if}}\n\n{{#if this.tem_procurador}}\n<p><em>Representado(a) por seu(sua) procurador(a):</em></p>\n<p>\nNome: {{this.procurador.nome}}<br>\nCPF: {{cpf this.procurador.cpf}}<br>\nRG: {{this.procurador.rg}}<br>\nEndereço: {{this.procurador.endereco}}, nº {{this.procurador.numero}}, Cidade: {{this.procurador.cidade}}-{{this.procurador.uf}}\n</p>\n{{/if}}\n\n{{else}}\n<p><strong>Promissária Compradora:</strong></p>\n<p>\nRazão Social: {{this.razao_social}}<br>\nCNPJ: nº {{cnpj this.cnpj}}<br>\nEndereço: {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}{{#if this.bairro}}, Bairro: {{this.bairro}}{{/if}}, Cidade: {{this.cidade}}-{{this.uf}}, CEP {{cep this.cep}}\n</p>\n<p>Neste ato representada por seu(s) representante(s) legal(is):</p>\n<p>\nNome Completo: {{this.representante.nome}}<br>\nCPF: {{cpf this.representante.cpf}}<br>\nNacionalidade: {{this.representante.nacionalidade}}<br>\nEstado Civil: {{this.representante.estado_civil}}<br>\nProfissão: {{this.representante.profissao}}{{#if (existe this.representante.email)}}<br>\nE-mail: {{this.representante.email}}{{/if}}{{#if (existe this.representante.mobile_phone)}}<br>\nTelefone: {{this.representante.mobile_phone}}{{/if}}\n</p>\n{{/if}}\n{{/each}}\n\n<h3>INTERMEDIADORA{{#if comissao.comissionados.length}}{{#if (gt comissao.comissionados.length 1)}}S{{/if}}{{/if}}</h3>\n\n{{#if comissao.comissionados.length}}\n{{#each comissao.comissionados}}\n<p>\n{{#if (eq tipo_pessoa \"fisica\")}}\nCorretor(a): {{nome}}<br>\nCPF: {{cpf cpf}}\n{{else}}\nImobiliária: {{nome}}<br>\nCNPJ: nº {{cnpj cnpj}}\n{{/if}}\n{{#if (existe papel_texto)}}<br>Função: {{papel_texto}}{{/if}}\n{{#if (existe creci)}}<br>CRECI: nº {{creci}}{{/if}}\n{{#if this.percentual}}<br>Participação: {{this.percentual}}%{{/if}}\n{{#if (existe email)}}<br>E-mail: {{email}}{{/if}}\n{{#if (existe mobile_phone)}}<br>Telefone: {{mobile_phone}}{{/if}}\n</p>\n{{/each}}\n{{else}}\n<p>\n{{#if (eq comissao.corretora_tipo_pessoa \"fisica\")}}\nCorretor(a): {{comissao.imobiliaria_nome}}<br>\nCPF: {{cpf comissao.imobiliaria_cnpj}}{{#if (existe comissao.creci)}}<br>\nCRECI: nº {{comissao.creci}}{{/if}}\n{{else}}\nImobiliária: {{comissao.imobiliaria_nome}}<br>\nCNPJ: nº {{cnpj comissao.imobiliaria_cnpj}}{{#if (existe comissao.creci)}}<br>\nCRECI: nº {{comissao.creci}}{{/if}}\n{{/if}}\n{{#if (existe comissao.imobiliaria_email)}}<br>E-mail: {{comissao.imobiliaria_email}}{{/if}}\n</p>\n{{/if}}\n\n<hr>\n\n<p class=\"doc-intro\">São partes integrantes do presente instrumento os qualificados acima, que, por estarem de pleno e comum acordo, celebram o presente <strong>Instrumento Particular de Compromisso de Venda e Compra</strong>, na modalidade de <strong>Financiamento Imobiliário</strong>, nos seguintes termos e condições:</p>\n\n<hr>\n\n<h2>CLÁUSULA PRIMEIRA - DO OBJETO</h2>\n\n<p><strong>1.1.</strong> O(s) PROMITENTE(S) VENDEDOR(ES) é(são) legítimo(s) possuidor(es) e proprietário(s) do imóvel adiante descrito{{#if (existe config.titulo_aquisitivo)}}, adquirido conforme {{config.titulo_aquisitivo}}{{#if (existe config.registro_aquisitivo)}}, devidamente registrado sob {{config.registro_aquisitivo}}{{/if}}{{/if}}, livre e desembaraçado de quaisquer ônus reais, dívidas, tributos em atraso, ações reais ou pessoais reipersecutórias, salvo as ressalvas expressamente consignadas neste instrumento.</p>\n\n{{#if (existe config.observacao_imovel)}}\n<p><strong>1.2.</strong> {{config.observacao_imovel}}</p>\n{{/if}}\n\n<h3>Descrição do Imóvel</h3>\n\n{{#each imoveis}}\n<p>\nEndereço: {{this.rua}}, nº {{this.numero}}{{#if this.complemento}}, Complemento: {{this.complemento}}{{/if}}, Bairro: {{this.bairro}}, Cidade: {{this.cidade}} - {{this.uf}}, CEP {{cep this.cep}}<br>\nMatrícula: nº {{this.matricula}} do {{this.cartorio}}<br>\nContribuinte: nº {{this.inscricao_iptu}} junto à Prefeitura local{{#if this.inscricao_municipal}}{{#unless (eq this.inscricao_municipal this.inscricao_iptu)}}<br>Inscrição Municipal: nº {{this.inscricao_municipal}}{{/unless}}{{/if}}<br>\n{{#if (existe this.sql)}}SQL: nº {{this.sql}}<br>{{/if}}\nDescrição: {{this.descricao}}\n</p>\n{{/each}}\n\n<hr>\n\n<h2>CLÁUSULA SEGUNDA - DO PREÇO</h2>\n\n<p><strong>2.1.</strong> O preço certo e ajustado para a presente transação é de {{moeda pagamento.valor_total}} ({{extenso pagamento.valor_total}}), a ser pago da seguinte forma:</p>\n\n<p><strong>a)</strong> Sinal e princípio de pagamento (arras confirmatórias): {{moeda pagamento.sinal_arras}} ({{extenso pagamento.sinal_arras}}), a ser creditado na conta do(s) PROMITENTE(S) VENDEDOR(ES) no prazo de 1 (um) dia útil contado da assinatura do presente instrumento.</p>\n\n<!-- CLAUSE_SLOT:G1 -->\n\n<p><strong>b)</strong> Financiamento imobiliário com alienação fiduciária em garantia{{#if (existe config.banco_financiamento)}}, junto à {{config.banco_financiamento}}{{/if}}: {{moeda pagamento.alienacao_fiduciaria}} ({{extenso pagamento.alienacao_fiduciaria}}), cujo valor será liberado pelo agente financeiro em favor do(s) PROMITENTE(S) VENDEDOR(ES) no prazo de até 10 (dez) dias úteis contados do registro do Contrato de Financiamento junto ao Cartório de Registro de Imóveis competente.</p>\n\n{{#if (gt pagamento.fgts 0)}}\n<p><strong>b.1)</strong> Do montante financiado, o valor de {{moeda pagamento.fgts}} ({{extenso pagamento.fgts}}) será proveniente de utilização de saldo do FGTS (Fundo de Garantia do Tempo de Serviço), conforme regras vigentes do agente financeiro e da Caixa Econômica Federal.</p>\n{{/if}}\n\n{{#if (gt pagamento.recursos_proprios 0)}}\n<p><strong>c)</strong> Recursos próprios do(s) PROMISSÁRIO(S) COMPRADOR(ES): {{moeda pagamento.recursos_proprios}} ({{extenso pagamento.recursos_proprios}}), a ser(em) creditado(s) na conta do(s) PROMITENTE(S) VENDEDOR(ES) no prazo de 5 (cinco) dias úteis contados da assinatura do presente instrumento.</p>\n{{/if}}\n\n{{#if pagamento.parcelas.length}}\n{{#each pagamento.parcelas}}\n<p><strong>Parcela {{this.numero}}.</strong> {{this.tipo_texto}}: {{moeda this.valor}} ({{extenso this.valor}}), {{#if (existe this.momento_data_texto)}}até {{this.momento_data_texto}}{{else}}em {{numero this.dias}} ({{numeroExtenso this.dias}}) dia(s) corridos {{#if (existe this.momento_texto)}}{{this.momento_texto}}{{else}}contados da assinatura deste instrumento{{/if}}{{/if}}, {{#if (existe this.meio_pagamento_texto)}}{{this.meio_pagamento_texto}}{{else}}mediante transferência bancária (TED ou PIX){{/if}}{{#if (existe this.destino_texto)}}, {{this.destino_texto}}{{else}} nas contas indicadas pelo(s) PROMITENTE(S) VENDEDOR(ES){{/if}}.</p>\n{{/each}}\n{{/if}}\n\n<!-- CLAUSE_SLOT:G4 -->\n\n<p><strong>2.1.{{subnum \"2.1\"}}.</strong> A não creditação do valor do sinal previsto na alínea \"a\" no prazo estipulado importará em rescisão automática do presente instrumento, independentemente de notificação judicial ou extrajudicial, retornando as partes ao <em>status quo ante</em>.</p>\n\n<p><strong>2.1.{{subnum \"2.1\"}}.</strong> Caso o agente financeiro aprove e libere valor inferior ao previsto na alínea \"b\", o(s) PROMISSÁRIO(S) COMPRADOR(ES) deverá(ão) complementar a diferença com recursos próprios, no prazo de 5 (cinco) dias úteis contados da comunicação da aprovação do financiamento, nos termos do art. 22 da Resolução BCB nº 4.676/2018.</p>\n\n<p><strong>2.1.{{subnum \"2.1\"}}.</strong> Os pagamentos referidos nesta cláusula deverão ser efetuados diretamente nas contas bancárias indicadas pelo(s) PROMITENTE(S) VENDEDOR(ES), mediante transferência eletrônica (TED, PIX ou DOC), servindo os comprovantes bancários como recibo de quitação parcial.</p>\n\n{{#if (existe config.saldo_devedor_vendedor)}}\n<p><strong>2.1.{{subnum \"2.1\"}}.</strong> Do valor liberado pelo agente financeiro, será automaticamente abatido pela instituição financeira o saldo devedor de alienação fiduciária existente em favor do(s) PROMITENTE(S) VENDEDOR(ES), no montante aproximado de {{moeda config.saldo_devedor_vendedor}} ({{extenso config.saldo_devedor_vendedor}}), sendo o eventual saldo remanescente creditado na conta indicada pelo(s) PROMITENTE(S) VENDEDOR(ES).</p>\n{{/if}}\n\n{{#if (existe config.permuta_descricao)}}\n<p><strong>2.1.{{subnum \"2.1\"}}.</strong> Parte do preço estipulado nesta cláusula é satisfeita mediante permuta, nos seguintes termos: {{config.permuta_descricao}}. A entrega efetiva do(s) bem(ns) permutado(s), com a documentação regularizada e livre de quaisquer ônus, é condição para a quitação parcial correspondente.</p>\n{{/if}}\n\n<hr>\n\n<h2>CLÁUSULA TERCEIRA - DA IMISSÃO NA POSSE</h2>\n\n<p><strong>3.1.</strong> A posse direta do imóvel será transferida ao(s) PROMISSÁRIO(S) COMPRADOR(ES), livre e desembaraçada de pessoas e coisas, {{#if (existe entrega_posse.momento_texto)}}{{entrega_posse.momento_texto}}{{else}}no prazo de 1 (um) dia útil contado do <strong>registro do Contrato de Financiamento com Alienação Fiduciária</strong> junto ao Cartório de Registro de Imóveis competente{{/if}}.</p>\n\n<p><strong>3.1.1.</strong> O atraso na entrega da posse por parte do(s) PROMITENTE(S) VENDEDOR(ES) sujeitará ao pagamento de multa diária no valor de {{moeda config.multa_diaria_posse}} ({{extenso config.multa_diaria_posse}}), a ser paga ao(s) PROMISSÁRIO(S) COMPRADOR(ES). Transcorridos 30 (trinta) dias de atraso, a multa diária será acrescida de 20% (vinte por cento) sobre o valor originário, sem prejuízo de eventuais perdas e danos.</p>\n\n<p><strong>3.2.</strong> O imóvel será entregue no estado em que se encontra, tendo o(s) PROMISSÁRIO(S) COMPRADOR(ES) vistoriado e aceito suas condições atuais{{#if (existe config.itens_entrega)}}, incluindo os seguintes itens, benfeitorias e acessórios: {{config.itens_entrega}}{{/if}}.</p>\n\n{{#if (existe config.locacao_situacao)}}\n{{#if (eq config.locacao_situacao \"vendedor-entregara\")}}\n<p><strong>3.3.</strong> O imóvel encontra-se atualmente ocupado por terceiro em contrato de locação. O(s) PROMITENTE(S) VENDEDOR(ES) compromete(m)-se a entregá-lo desocupado{{#if (existe config.locacao_data)}}, até {{config.locacao_data}}{{/if}}, livre de quaisquer ocupantes e de seus pertences, sob pena de rescisão por culpa do(s) PROMITENTE(S) VENDEDOR(ES).</p>\n{{else}}\n<p><strong>3.3.</strong> O imóvel encontra-se atualmente ocupado por terceiro em contrato de locação{{#if (existe config.locacao_data)}}, com vigência prevista até {{config.locacao_data}}{{/if}}. O(s) PROMISSÁRIO(S) COMPRADOR(ES) declara(m) ciência e concordância em manter o contrato de locação vigente, sub-rogando-se nos direitos e obrigações do locador a partir da imissão na posse.</p>\n{{/if}}\n{{/if}}\n\n<!-- CLAUSE_SLOT:G2 -->\n\n<hr>\n\n<h2>CLÁUSULA QUARTA - DO INSTRUMENTO DEFINITIVO</h2>\n\n<p><strong>4.1.</strong> O(s) PROMISSÁRIO(S) COMPRADOR(ES) terá(ão) o prazo de 45 (quarenta e cinco) dias úteis, contados da assinatura do presente instrumento, para a formalização do Contrato de Financiamento Imobiliário com Alienação Fiduciária em Garantia junto ao agente financeiro de sua escolha. O(s) PROMITENTE(S) VENDEDOR(ES) compromete(m)-se a atender prontamente todas as convocações do agente financeiro para assinatura do referido contrato.</p>\n\n<p><strong>4.2.</strong> O(s) PROMISSÁRIO(S) COMPRADOR(ES) deverá(ão) apresentar toda a documentação pessoal e financeira exigida pelo agente financeiro no prazo máximo de 20 (vinte) dias úteis contados da assinatura deste instrumento, responsabilizando-se pela veracidade e atualidade dos documentos apresentados.</p>\n\n<p><strong>4.3.</strong> Todas as despesas relativas à formalização do financiamento, incluindo ITBI (Imposto sobre Transmissão de Bens Imóveis), FRJ (Fundo de Reaparelhamento do Judiciário), emolumentos cartorários, taxas de avaliação do imóvel e demais custos atinentes à transferência, correrão por conta exclusiva do(s) PROMISSÁRIO(S) COMPRADOR(ES). O protocolo do título para registro deverá ser realizado no prazo de 1 (um) dia útil após a assinatura do Contrato de Financiamento.</p>\n\n<p><strong>4.4.</strong> As partes comprometem-se a apresentar, tempestivamente, toda a documentação exigida pelo agente financeiro e pelo Cartório de Registro de Imóveis, incluindo, mas não se limitando a: certidões negativas de débitos federais, estaduais e municipais; certidões dos distribuidores cíveis, criminais e trabalhistas; certidão de matrícula atualizada do imóvel; e quaisquer outros documentos que se façam necessários para a aprovação do crédito e o registro do contrato.</p>\n\n<p><strong>4.5.</strong> O registro do Contrato de Financiamento junto ao Cartório de Registro de Imóveis competente deverá ser concluído no prazo de 30 (trinta) dias contados do protocolo. Na hipótese de o Cartório emitir nota de exigência, os prazos previstos nesta cláusula ficarão suspensos até o efetivo cumprimento das exigências pela parte responsável.</p>\n\n<p><strong>4.6.</strong> O(s) PROMITENTE(S) VENDEDOR(ES) declara(m) ter plena ciência de que a liberação dos valores referentes ao financiamento somente ocorrerá após o efetivo registro do Contrato de Financiamento com Alienação Fiduciária junto ao Cartório de Registro de Imóveis, não cabendo qualquer reclamação quanto a eventuais demoras decorrentes do trâmite cartorário.</p>\n\n<p><strong>4.7.</strong> O(s) PROMITENTE(S) VENDEDOR(ES) garante(m) que o imóvel objeto deste instrumento encontra-se em condições de ser aceito pela engenharia do agente financeiro, sem restrições estruturais, legais ou documentais que impeçam ou dificultem a aprovação do financiamento, responsabilizando-se por quaisquer prejuízos decorrentes de informações inverídicas ou omissões.</p>\n\n<hr>\n\n<h2>CLÁUSULA QUINTA - DOS TRIBUTOS E ENCARGOS</h2>\n\n<p><strong>5.1.</strong> Todos os tributos, taxas, contribuições e encargos incidentes sobre o imóvel (incluindo IPTU, taxas de condomínio, água, luz, gás e demais despesas <em>propter rem</em>) são de responsabilidade exclusiva do(s) PROMITENTE(S) VENDEDOR(ES) até a data da efetiva entrega da posse ao(s) PROMISSÁRIO(S) COMPRADOR(ES), passando a ser de responsabilidade deste(s) a partir de então, calculados <em>pro rata die</em> no mês de transição.</p>\n\n<p><strong>5.1.1.</strong> O(s) PROMISSÁRIO(S) COMPRADOR(ES) deverá(ão) providenciar a transferência de titularidade das contas de consumo (água, luz, gás, condomínio) junto aos respectivos órgãos e concessionárias, no prazo de 30 (trinta) dias contados da imissão na posse.</p>\n\n{{#if (eq config.tem_debitos true)}}\n<p><strong>5.2.</strong> O(s) PROMITENTE(S) VENDEDOR(ES) declara(m) a existência dos seguintes débitos pendentes sobre o imóvel, cuja quitação será de sua exclusiva responsabilidade{{#if (existe config.debitos_assumidos_descricao)}}, ressalvada a exceção da Cláusula 5.3{{/if}}, devendo ser comprovada antes da liberação dos valores pelo agente financeiro:</p>\n<ul>\n{{#if (existe config.debito_iptu_valor)}}<li>IPTU em atraso: {{moeda config.debito_iptu_valor}} ({{extenso config.debito_iptu_valor}});</li>{{/if}}\n{{#if (existe config.debito_condominio_valor)}}<li>Despesas condominiais em atraso: {{moeda config.debito_condominio_valor}} ({{extenso config.debito_condominio_valor}});</li>{{/if}}\n{{#if (existe config.debito_outros_descricao)}}<li>Outros débitos: {{config.debito_outros_descricao}}.</li>{{/if}}\n</ul>\n{{/if}}\n\n{{#if (existe config.debitos_assumidos_descricao)}}\n<p><strong>5.3.</strong> Em derrogação parcial às cláusulas anteriores, o(s) PROMISSÁRIO(S) COMPRADOR(ES) assume(m) expressamente, com pleno conhecimento de causa, o pagamento dos seguintes débitos: {{config.debitos_assumidos_descricao}}. O valor assumido foi considerado na composição do preço pactuado na Cláusula Segunda.</p>\n{{/if}}\n\n{{#if (existe config.regularizacoes_descricao)}}\n<p><strong>5.4.</strong> O(s) PROMITENTE(S) VENDEDOR(ES) compromete(m)-se a promover, às suas exclusivas expensas, as seguintes regularizações pendentes: {{config.regularizacoes_descricao}}. O prazo para conclusão é de {{#if (existe config.regularizacoes_prazo_dias)}}{{numero config.regularizacoes_prazo_dias}} ({{numeroExtenso config.regularizacoes_prazo_dias}}){{else}}30 (trinta){{/if}} dias corridos contados da assinatura deste instrumento, sendo certo que a não conclusão tempestiva pode prejudicar a aprovação do financiamento pela engenharia do agente financeiro, hipótese em que se aplica a Cláusula 9.5.</p>\n{{/if}}\n\n<hr>\n\n<h2>CLÁUSULA SEXTA - DA IRREVOGABILIDADE E IRRETRATABILIDADE</h2>\n\n<p><strong>6.1.</strong> O presente instrumento é celebrado em caráter irrevogável e irretratável, obrigando as partes, seus herdeiros e sucessores, renunciando expressamente à faculdade de arrependimento prevista no art. 420 do Código Civil, ressalvadas as hipóteses de rescisão expressamente previstas neste contrato.</p>\n\n<hr>\n\n<h2>CLÁUSULA SÉTIMA - DA DOCUMENTAÇÃO</h2>\n\n<p><strong>7.1.</strong> No prazo de 7 (sete) dias contados da assinatura do presente instrumento, o(s) PROMITENTE(S) VENDEDOR(ES) deverá(ão) apresentar ao(s) PROMISSÁRIO(S) COMPRADOR(ES) toda a documentação relativa ao imóvel e às pessoas dos proprietários, incluindo certidões reais, forenses e pessoais reipersecutórias.</p>\n\n<p><strong>7.2.</strong> A documentação do imóvel deverá contemplar, no mínimo: certidão de matrícula atualizada (com negativa de ônus e ações reais reipersecutórias), certidões negativas de débitos municipais (IPTU), certidão negativa de débitos condominiais (quando aplicável) e demais documentos exigidos pelo agente financeiro.</p>\n\n<p><strong>7.3.</strong> Na hipótese de qualquer das certidões apresentar apontamento positivo que represente risco eviccionário ao(s) PROMISSÁRIO(S) COMPRADOR(ES), ou que impeça a aprovação do financiamento pelo agente financeiro, qualquer das partes poderá rescindir o presente instrumento, retornando ao <em>status quo ante</em>, com a integral restituição dos valores eventualmente pagos.</p>\n\n<p><strong>7.4.</strong> Enquanto pendente a entrega e análise da documentação prevista nesta cláusula, os pagamentos subsequentes ao sinal ficarão suspensos, sem que isso configure mora do(s) PROMISSÁRIO(S) COMPRADOR(ES).</p>\n\n<hr>\n\n<h2>CLÁUSULA OITAVA - DA INADIMPLÊNCIA</h2>\n\n<p><strong>8.1.</strong> O descumprimento de qualquer obrigação prevista neste instrumento, incluindo, mas não se limitando ao disposto no item 4.1 (prazo para formalização do financiamento), sujeitará a parte inadimplente ao pagamento de multa moratória de {{numero config.multa_penal_moratoria}}% ({{numeroExtenso config.multa_penal_moratoria}} por cento) sobre o valor da obrigação descumprida, acrescida de juros moratórios de {{numero config.juros_mensais_atraso}}% ({{numeroExtenso config.juros_mensais_atraso}} por cento) ao mês, calculados <em>pro rata die</em>, sem prejuízo das demais cominações previstas neste contrato. A parte inadimplente terá o prazo de {{numero config.prazo_atraso_rescisao}} ({{numeroExtenso config.prazo_atraso_rescisao}}) dias para a purgação da mora, contados da notificação escrita.</p>\n\n<hr>\n\n<h2>CLÁUSULA NONA - DA RESCISÃO</h2>\n\n<p><strong>9.1.</strong> Na hipótese de rescisão por culpa exclusiva do(s) PROMISSÁRIO(S) COMPRADOR(ES), este(s) pagará(ão) ao(s) PROMITENTE(S) VENDEDOR(ES) multa compensatória equivalente a {{numero config.multa_penal_compensatoria}}% ({{numeroExtenso config.multa_penal_compensatoria}} por cento) do valor total do contrato, podendo o(s) PROMITENTE(S) VENDEDOR(ES) reter tal quantia dos valores já pagos, devolvendo o saldo remanescente em até {{numero config.prazo_multa_rescisoria}} ({{numeroExtenso config.prazo_multa_rescisoria}}) dias.</p>\n\n<p><strong>9.2.</strong> Na hipótese de rescisão por culpa exclusiva do(s) PROMITENTE(S) VENDEDOR(ES), este(s) restituirá(ão) integralmente os valores recebidos ao(s) PROMISSÁRIO(S) COMPRADOR(ES), acrescidos de multa compensatória equivalente a {{numero config.multa_penal_compensatoria}}% ({{numeroExtenso config.multa_penal_compensatoria}} por cento) do valor total do contrato, no prazo de {{numero config.prazo_multa_rescisoria}} ({{numeroExtenso config.prazo_multa_rescisoria}}) dias contados da formalização da rescisão.</p>\n\n<p><strong>9.3.</strong> A rescisão por mútuo acordo dispensará a aplicação das multas previstas nos itens 9.1 e 9.2, devendo os valores pagos ser restituídos integralmente ao(s) PROMISSÁRIO(S) COMPRADOR(ES) no prazo acordado entre as partes.</p>\n\n<p><strong>9.4.</strong> Em qualquer hipótese de rescisão, a comissão de intermediação prevista na Cláusula Décima Quarta será devida por quem der causa ao desfazimento do negócio.</p>\n\n<p><strong>9.5.</strong> Na hipótese de a não obtenção do financiamento imobiliário previsto na alínea \"b\" da Cláusula Segunda decorrer de reprovação cadastral, documental ou de engenharia pelo agente financeiro, por motivos alheios à vontade do(s) PROMISSÁRIO(S) COMPRADOR(ES) e não imputáveis ao(s) PROMITENTE(S) VENDEDOR(ES), o presente instrumento será rescindido de pleno direito, independentemente de notificação judicial ou extrajudicial, com a <strong>restituição integral e sem penalidades</strong> de todos os valores pagos pelo(s) PROMISSÁRIO(S) COMPRADOR(ES), no prazo de 15 (quinze) dias contados da comunicação formal da negativa do financiamento.</p>\n\n{{#if (eq config.desistencia_permite true)}}\n<p><strong>9.6.</strong> Fica facultado ao(s) PROMISSÁRIO(S) COMPRADOR(ES), no prazo de {{#if (existe config.desistencia_prazo_dias)}}{{numero config.desistencia_prazo_dias}} ({{numeroExtenso config.desistencia_prazo_dias}}){{else}}7 (sete){{/if}} dias corridos contados da assinatura deste instrumento, o direito de desistência sem qualquer penalidade, mediante notificação escrita ao(s) PROMITENTE(S) VENDEDOR(ES) e restituição integral dos valores eventualmente pagos no prazo de 5 (cinco) dias úteis contados da notificação.</p>\n{{/if}}\n\n<!-- CLAUSE_SLOT:G3 -->\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA - DA NÃO MODIFICAÇÃO</h2>\n\n<p><strong>10.1.</strong> As condições estabelecidas neste instrumento deverão ser cumpridas tal como redigidas. A tolerância de qualquer das partes quanto ao descumprimento de quaisquer cláusulas ou condições será considerada mera liberalidade, não configurando novação, renúncia, modificação ou alteração do pactuado, podendo a parte tolerante exigir o cumprimento integral a qualquer tempo.</p>\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA PRIMEIRA - DAS DECLARAÇÕES</h2>\n\n<p><strong>11.1.</strong> O(s) PROMITENTE(S) VENDEDOR(ES) declara(m) que o imóvel objeto deste instrumento encontra-se livre e desembaraçado de quaisquer ônus reais, gravames, penhoras, arrestos, sequestros, usufrutos, servidões, dívidas, tributos em atraso, ações reais ou pessoais reipersecutórias, salvo as ressalvas expressamente consignadas neste instrumento, responsabilizando-se pela evicção em qualquer grau.</p>\n\n<p><strong>11.2.</strong> O(s) PROMISSÁRIO(S) COMPRADOR(ES) declara(m) possuir aptidão creditícia e condições financeiras para a obtenção do financiamento imobiliário previsto na alínea \"b\" da Cláusula Segunda, comprometendo-se a envidar os melhores esforços para a aprovação do crédito junto ao agente financeiro.</p>\n\n<p><strong>11.3.</strong> As partes declaram que a presente transação é celebrada em caráter <em>ad corpus</em>, de modo que eventuais diferenças de metragem encontradas não darão ensejo a complemento de preço ou devolução de valores, nos termos do art. 500 do Código Civil.</p>\n\n<p><strong>11.4.</strong> As partes declaram, sob as penas da lei, que não mantêm relações de união estável com terceiros não nominados neste instrumento, nos termos do art. 1.723 do Código Civil, responsabilizando-se civil e criminalmente pela veracidade desta declaração.</p>\n\n{{#if (existe config.vicios_opcao)}}\n{{#if (eq config.vicios_opcao \"renuncia\")}}\n<p><strong>11.5.</strong> O(s) PROMISSÁRIO(S) COMPRADOR(ES) declara(m) ter vistoriado o imóvel no estado em que se encontra e o aceita(m) como tal, renunciando expressamente ao direito de pleitear qualquer indenização, abatimento de preço ou rescisão em razão de vícios redibitórios aparentes, ressalvada a hipótese de vícios ocultos não detectáveis em vistoria normal e dos quais o(s) PROMITENTE(S) VENDEDOR(ES) tinha(m) ciência prévia, hipótese em que respondem pela evicção nos termos dos arts. 441 a 446 do Código Civil.</p>\n{{else}}\n{{#if (eq config.vicios_opcao \"detalhado\")}}\n<p><strong>11.5.</strong> O(s) PROMITENTE(S) VENDEDOR(ES) declara(m), sob as penas da lei, que o imóvel se encontra livre de vícios construtivos, redibitórios ou ocultos, responsabilizando-se nos termos dos arts. 441 a 446 do Código Civil pelos vícios eventualmente descobertos pelo(s) PROMISSÁRIO(S) COMPRADOR(ES) no prazo legal.</p>\n{{else}}\n{{#if (eq config.vicios_opcao \"reparar\")}}\n<p><strong>11.5.</strong> O(s) PROMITENTE(S) VENDEDOR(ES) compromete(m)-se a realizar, às suas exclusivas expensas, os seguintes reparos antes da entrega da posse: {{config.vicios_descricao}}. A não execução tempestiva e adequada dos reparos autoriza o(s) PROMISSÁRIO(S) COMPRADOR(ES) a executá-los e descontar o respectivo valor do saldo do preço, ou a rescindir o contrato sem ônus, com restituição integral dos valores pagos.</p>\n{{else}}\n{{#if (eq config.vicios_opcao \"desocultados\")}}\n<p><strong>11.5.</strong> O(s) PROMITENTE(S) VENDEDOR(ES) declara(m), com expressa ciência e concordância do(s) PROMISSÁRIO(S) COMPRADOR(ES), a existência dos seguintes vícios construtivos ou ocultos no imóvel: {{config.vicios_descricao}}. O(s) PROMISSÁRIO(S) COMPRADOR(ES), cientes destes vícios, renuncia(m) ao direito de pleitear sua reparação, indenização ou abatimento de preço com fundamento nos vícios ora declarados.</p>\n{{/if}}\n{{/if}}\n{{/if}}\n{{/if}}\n{{/if}}\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA SEGUNDA - DO REQUERIMENTO</h2>\n\n<p><strong>12.1.</strong> As partes autorizam e requerem ao Oficial do Cartório de Registro de Imóveis competente que proceda ao registro do Contrato de Financiamento com Alienação Fiduciária em Garantia, bem como às averbações e demais atos registrais necessários à perfeita formalização da presente transação, nos termos da legislação vigente.</p>\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA TERCEIRA - DAS COMUNICAÇÕES</h2>\n\n<p><strong>13.1.</strong> Todas as comunicações, notificações e interpelações entre as partes serão realizadas preferencialmente por meio eletrônico (e-mail e/ou WhatsApp), nos endereços e números informados na qualificação das partes, considerando-se recebidas na data do envio, desde que haja confirmação de leitura ou entrega. As notificações formais poderão ser realizadas por meio de carta com aviso de recebimento (AR) ou por intermédio de Cartório de Títulos e Documentos, nos endereços constantes deste instrumento.</p>\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA QUARTA - DA COMISSÃO</h2>\n\n{{#if (gt comissao.comissionados.length 1)}}\n<p><strong>14.1.</strong> Pela intermediação e assessoria prestadas, será devida comissão de corretagem total no valor de {{moeda comissao.valor}} ({{extenso comissao.valor}}), equivalente a {{percentual comissao.valor pagamento.valor_total}} do valor total da transação, a ser paga pela {{#if (existe comissao.quem_paga_texto)}}{{comissao.quem_paga_texto}}{{else}}Parte Compradora{{/if}}{{#if (existe comissao.quando_paga_texto)}} {{comissao.quando_paga_texto}}{{/if}}, distribuída entre os comissionados conforme abaixo:</p>\n<ul>\n{{#each comissao.comissionados}}\n<li>{{#if (eq tipo_pessoa \"fisica\")}}ao(à) corretor(a) {{nome}}, inscrito(a) no CPF nº {{cpf cpf}}{{else}}à imobiliária {{nome}}, inscrita no CNPJ nº {{cnpj cnpj}}{{/if}}{{#if (existe creci)}}, CRECI nº {{creci}}{{/if}}{{#if (existe papel_texto)}} ({{papel_texto}}){{/if}} — {{#if this.percentual}}{{this.percentual}}% = {{/if}}{{moeda valor}} ({{extenso valor}}).</li>\n{{/each}}\n</ul>\n{{else}}\n<p><strong>14.1.</strong> Pela intermediação e assessoria prestadas, será devida a comissão de corretagem no valor total de {{moeda comissao.valor}} ({{extenso comissao.valor}}), equivalente a {{percentual comissao.valor pagamento.valor_total}} do valor total da transação, a ser paga pela {{comissao.quem_paga_texto}} {{#if (eq comissao.corretora_tipo_pessoa \"fisica\")}}ao(à) corretor(a) {{comissao.imobiliaria_nome}}, inscrito(a) no CPF nº {{cpf comissao.imobiliaria_cnpj}}{{else}}à imobiliária intermediadora {{comissao.imobiliaria_nome}}, inscrita no CNPJ nº {{cnpj comissao.imobiliaria_cnpj}}{{/if}}{{#if (existe comissao.creci)}}, CRECI nº {{comissao.creci}}{{/if}}.</p>\n{{/if}}\n\n<p><strong>14.2.</strong> {{#if (existe comissao.quando_paga_texto)}}O pagamento da comissão será efetuado {{comissao.quando_paga_texto}}, no prazo de até 5 (cinco) dias úteis contados do respectivo evento.{{else}}O pagamento da comissão está atrelado à liberação dos recursos previstos na alínea \"b\" da Cláusula Segunda (financiamento imobiliário), devendo ser efetuado no prazo de até 5 (cinco) dias úteis contados da efetiva liberação dos valores pelo agente financeiro em favor do(s) PROMITENTE(S) VENDEDOR(ES).{{/if}}</p>\n\n<p><strong>14.3.</strong> A comissão de corretagem é devida pela efetiva aproximação das partes e conclusão do negócio, sendo líquida, certa e exigível, de modo que eventual inadimplência ensejará cobrança extrajudicial ou ação executiva, na forma da lei.</p>\n\n<p><strong>14.4.</strong> Os intermediadores poderão, conjunta ou isoladamente, ceder ou vincular seus direitos de crédito sobre as comissões, inclusive como garantia em operações de crédito.</p>\n\n<!-- CLAUSE_SLOT:G5 -->\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA QUINTA - DA LGPD</h2>\n\n<p><strong>15.1.</strong> As partes declaram ciência e concordância com o tratamento de seus dados pessoais, nos termos da Lei nº 13.709/2018 (Lei Geral de Proteção de Dados Pessoais - LGPD), para as finalidades estritamente necessárias à execução do presente contrato, incluindo a coleta, uso, armazenamento, compartilhamento e proteção dos dados, em conformidade com a Política de Privacidade da intermediadora.</p>\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA SEXTA - DA CONTRATAÇÃO ELETRÔNICA</h2>\n\n<p><strong>16.1.</strong> O presente instrumento é firmado em meio eletrônico, com a utilização de assinaturas eletrônicas, nos termos da Medida Provisória nº 2.200-2/2001, que instituiu a Infraestrutura de Chaves Públicas Brasileira (ICP-Brasil) e equiparou os documentos eletrônicos assinados digitalmente aos documentos físicos.</p>\n\n<p><strong>16.2.</strong> As partes reconhecem a validade jurídica, a eficácia e a força probante do presente instrumento em formato eletrônico, dispensando a necessidade de formalização em meio físico, nos termos do art. 10, §2º, da MP nº 2.200-2/2001.</p>\n\n<hr>\n\n<h2>CLÁUSULA DÉCIMA SÉTIMA - DO FORO</h2>\n\n{{#if (eq foro \"arbitragem\")}}\n<p><strong>17.1.</strong> Para dirimir eventuais disputas e controvérsias envolvendo o presente instrumento, as partes expressamente elegem, por convenção de arbitragem e exclusão de qualquer outro foro, nos termos do artigo 5º e do §1º do artigo 4º da Lei nº 9.307/1996, os seguintes foros privados:</p>\n\n<ul>\n  <li>TASP (Centro de Mediação e Arbitragem de São Paulo) — https://www.arbitragem.com.br/</li>\n  <li>ACORDIA — https://acordia.com.br/</li>\n</ul>\n\n<p><strong>17.2.</strong> Fica acordado que a parte interessada em submeter a controvérsia à arbitragem poderá escolher livremente entre as câmaras arbitrais elencadas acima, respeitando-se o regulamento interno da câmara escolhida, cujos custos serão suportados pela parte requerente, salvo disposição diversa no laudo arbitral.</p>\n{{else}}\n<p><strong>17.1.</strong> Para dirimir quaisquer dúvidas ou controvérsias oriundas do presente instrumento, as partes elegem o foro da situação do imóvel, com exclusão de qualquer outro, por mais privilegiado que seja.</p>\n{{/if}}\n\n<hr>\n\n<p>E por estarem assim justas e contratadas, as partes firmam o presente instrumento em meio eletrônico, na presença das testemunhas abaixo identificadas.</p>\n\n<p>{{config.municipio_imovel}}{{#if (existe config.data_assinatura)}}, {{dataExtenso config.data_assinatura}}{{/if}}.</p>\n\n<div class=\"assinaturas\">\n\n<h3>PROMITENTE(S) VENDEDOR(ES)</h3>\n{{#each vendedores}}\n<p>_______________________________<br>{{this.nome}}<br>CPF: {{cpf this.cpf}}</p>\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p>_______________________________<br>{{this.conjuge.nome}}<br>CPF: {{cpf this.conjuge.cpf}}<br>(Cônjuge/Companheiro(a))</p>\n{{/if}}{{/if}}\n{{/each}}\n\n<h3>PROMISSÁRIO(S) COMPRADOR(ES)</h3>\n{{#each compradores}}\n<p>_______________________________<br>{{this.nome}}<br>CPF: {{cpf this.cpf}}</p>\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p>_______________________________<br>{{this.conjuge.nome}}<br>CPF: {{cpf this.conjuge.cpf}}<br>(Cônjuge/Companheiro(a))</p>\n{{/if}}{{/if}}\n{{/each}}\n\n<h3>INTERMEDIADORA{{#if comissao.comissionados.length}}{{#if (gt comissao.comissionados.length 1)}}S{{/if}}{{/if}}</h3>\n{{#if comissao.comissionados.length}}\n{{#each comissao.comissionados}}\n{{#unless (eq incluir_como_signatario false)}}\n<p>_______________________________<br>{{nome}}<br>{{#if (eq tipo_pessoa \"fisica\")}}CPF: {{cpf cpf}}{{else}}CNPJ: {{cnpj cnpj}}{{/if}}{{#if (existe creci)}}<br>CRECI: {{creci}}{{/if}}</p>\n{{/unless}}\n{{/each}}\n{{else}}\n<p>_______________________________<br>{{comissao.imobiliaria_nome}}<br>{{#if (eq comissao.corretora_tipo_pessoa \"fisica\")}}CPF: {{cpf comissao.imobiliaria_cnpj}}{{else}}CNPJ: {{cnpj comissao.imobiliaria_cnpj}}{{/if}}{{#if (existe comissao.creci)}}<br>CRECI: {{comissao.creci}}{{/if}}</p>\n{{/if}}\n\n<h3>TESTEMUNHAS</h3>\n{{#each testemunhas}}\n<p>_______________________________<br>Nome: {{#if this.nome}}{{this.nome}}{{else}}___________________________{{/if}}<br>CPF: {{#if this.cpf}}{{cpf this.cpf}}{{else}}___________________________{{/if}}</p>\n{{/each}}\n\n</div>\n\n</div>\n",
  "locacao_residencial_v3.hbs": "<div class=\"contrato\">\n\n<h1>INSTRUMENTO PARTICULAR DE CONTRATO DE LOCAÇÃO DE IMÓVEL PARA FINS RESIDENCIAIS</h1>\n\n<p>Pelo presente instrumento particular de contrato de locação, de um lado, como LOCADOR(A) e doravante nomeada PARTE LOCADORA, {{#each locadores}}{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{#if (existe this.nacionalidade)}}, {{this.nacionalidade}}{{/if}}{{#if (existe this.estado_civil)}}, {{this.estado_civil}}{{/if}}{{#if (existe this.profissao)}}, {{this.profissao}}{{/if}}{{#if (existe this.rg)}}, portador(a) da cédula de identidade RG nº {{this.rg}}{{/if}}{{#if (existe this.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.cpf}}{{/if}}{{#if (existe this.endereco)}}, residente e domiciliado(a) na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if (existe this.email)}}, endereço eletrônico e-mail {{this.email}}{{/if}}{{else}}{{this.razao_social}}, pessoa jurídica de direito privado, inscrita no CNPJ/MF sob nº {{cnpj this.cnpj}}{{#if (existe this.endereco)}}, com sede na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if this.representante.nome}}, neste ato representada por {{this.representante.nome}}, inscrito(a) no CPF/MF sob nº {{cpf this.representante.cpf}}{{/if}}{{/if}}{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}, casado(a) com {{this.conjuge.nome}}{{#if (existe this.conjuge.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.conjuge.cpf}}{{/if}}{{/if}}{{/if}}{{#unless @last}}; {{/unless}}{{/each}}, e de outro lado, como LOCATÁRIO(A) e doravante nomeada PARTE LOCATÁRIA, {{#each locatarios}}{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{#if (existe this.nacionalidade)}}, {{this.nacionalidade}}{{/if}}{{#if (existe this.estado_civil)}}, {{this.estado_civil}}{{/if}}{{#if (existe this.profissao)}}, {{this.profissao}}{{/if}}{{#if (existe this.rg)}}, portador(a) da cédula de identidade RG nº {{this.rg}}{{/if}}{{#if (existe this.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.cpf}}{{/if}}{{#if (existe this.endereco)}}, residente e domiciliado(a) na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if (existe this.email)}}, endereço eletrônico e-mail {{this.email}}{{/if}}{{else}}{{this.razao_social}}, pessoa jurídica de direito privado, inscrita no CNPJ/MF sob nº {{cnpj this.cnpj}}{{#if (existe this.endereco)}}, com sede na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if this.representante.nome}}, neste ato representada por {{this.representante.nome}}, inscrito(a) no CPF/MF sob nº {{cpf this.representante.cpf}}{{/if}}{{/if}}{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}, casado(a) com {{this.conjuge.nome}}{{#if (existe this.conjuge.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.conjuge.cpf}}{{/if}}{{/if}}{{/if}}{{#unless @last}}; {{/unless}}{{/each}}{{#if (eq garantia.tipo \"fiador\")}}, e, na qualidade de FIADOR(A), {{#if (eq garantia.fiador.tipo_pessoa \"juridica\")}}{{garantia.fiador.razao_social}}, pessoa jurídica de direito privado, inscrita no CNPJ/MF sob nº {{cnpj garantia.fiador.cnpj}}{{#if (existe garantia.fiador.endereco)}}, com sede na {{garantia.fiador.endereco}}, nº {{garantia.fiador.numero}}{{#if garantia.fiador.bairro}}, {{garantia.fiador.bairro}}{{/if}}{{#if (existe garantia.fiador.cep)}}, CEP {{cep garantia.fiador.cep}}{{/if}}{{#if (existe garantia.fiador.cidade)}}, {{garantia.fiador.cidade}}/{{garantia.fiador.uf}}{{/if}}{{/if}}{{#if garantia.fiador.representante.nome}}, neste ato representada por {{garantia.fiador.representante.nome}}, inscrito(a) no CPF/MF sob nº {{cpf garantia.fiador.representante.cpf}}{{/if}}{{else}}{{garantia.fiador.nome}}{{#if (existe garantia.fiador.nacionalidade)}}, {{garantia.fiador.nacionalidade}}{{/if}}{{#if (existe garantia.fiador.estado_civil)}}, {{garantia.fiador.estado_civil}}{{/if}}{{#if (existe garantia.fiador.rg)}}, portador(a) da cédula de identidade RG nº {{garantia.fiador.rg}}{{/if}}{{#if (existe garantia.fiador.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf garantia.fiador.cpf}}{{/if}}{{#if (existe garantia.fiador.endereco)}}, residente e domiciliado(a) na {{garantia.fiador.endereco}}, nº {{garantia.fiador.numero}}, {{garantia.fiador.cidade}}/{{garantia.fiador.uf}}{{/if}}{{/if}}{{/if}}, têm entre si, justo e acertado o seguinte:</p>\n\n<h2>1. IMÓVEL</h2>\n<p>1.1. A PARTE LOCADORA, proprietária do(a) {{#if (existe imovel.tipo_texto)}}{{imovel.tipo_texto}}{{else}}{{imovel.kind}}{{/if}}{{#if (existe imovel.complemento)}} {{imovel.complemento}}{{/if}}{{#if (existe imovel.condominio_nome)}}, do {{imovel.condominio_nome}}{{/if}}{{#if (existe imovel.rua)}}, localizado(a) na {{imovel.rua}}{{#if (existe imovel.numero)}}, nº {{imovel.numero}}{{/if}}{{/if}}{{#if imovel.bairro}}, {{imovel.bairro}}{{/if}}{{#if (existe imovel.cep)}}, CEP {{cep imovel.cep}}{{/if}}{{#if (existe imovel.cidade)}}, {{imovel.cidade}}{{#if (existe imovel.uf)}}/{{imovel.uf}}{{/if}}{{/if}}{{#if (gt imovel.area 0)}}, com área de {{numero imovel.area}} m²{{/if}}{{#if (gt imovel.vagas_garagem 0)}}, com {{imovel.vagas_garagem}} ({{numeroExtenso imovel.vagas_garagem \"f\"}}) vaga(s) de garagem{{/if}}{{#if imovel.inscricao_iptu}}, regularmente cadastrado na Prefeitura Municipal de {{imovel.cidade}} pelo contribuinte nº {{imovel.inscricao_iptu}}{{/if}}{{#if imovel.matricula}}, objeto da matrícula nº {{imovel.matricula}}{{#if imovel.cartorio}} do {{imovel.cartorio}}{{/if}}{{/if}}, pelo presente e na melhor forma de direito, loca-o à PARTE LOCATÁRIA, mediante as cláusulas e condições seguintes.</p>\n<p>1.2. Descrição do imóvel: {{imovel.descricao}}</p>\n\n<h2>2. PRAZO</h2>\n<p>2.1. O prazo de locação é de {{aluguel.vigencia_meses}} ({{numeroExtenso aluguel.vigencia_meses}}) meses{{#if (existe config.vigencia_inicio_texto)}}, a contar de {{config.vigencia_inicio_texto}}{{/if}}{{#if (existe config.vigencia_fim_texto)}} e com término fixado em {{config.vigencia_fim_texto}}{{/if}}, data em que a PARTE LOCATÁRIA se compromete a devolver o imóvel completamente livre e desocupado de coisas e pessoas.</p>\n<p>2.1.1. Findo o prazo estipulado, se a PARTE LOCATÁRIA permanecer no imóvel por mais de 30 (trinta) dias sem oposição da PARTE LOCADORA, presumir-se-á prorrogada a locação nas condições ajustadas, passando o contrato a vigorar por prazo indeterminado.</p>\n<p>2.1.2. Para a devolução do imóvel e entrega das chaves, por qualquer motivo que seja, mesmo que por término do contrato, ou após, se a locação se prorrogar por prazo indeterminado, obriga-se a PARTE LOCATÁRIA a notificar por escrito a PARTE LOCADORA com antecedência mínima de 30 (trinta) dias da desocupação.</p>\n\n<h2>3. ALUGUEL</h2>\n<p>3.1. O valor do aluguel mensal é de {{moeda aluguel.valor}} ({{extenso aluguel.valor}}) que se corrigirá a cada 12 (doze) meses, {{#if (eq aluguel.indice_reajuste \"IGPM\")}}pelo Índice Geral de Preços - Mercado (IGP-M){{else if (eq aluguel.indice_reajuste \"IPCA\")}}pelo Índice Nacional de Preços ao Consumidor Amplo (IPCA){{else}}pelo índice ajustado entre as partes{{/if}} pelo tempo que perdurar a locação, ou o índice que, em sua substituição, for eventualmente imposto.</p>\n<p>3.2. Não se aplica ao presente contrato para fins de reajuste do valor locativo, a variação negativa do índice indicado para medir a inflação no período.</p>\n\n<h2>4. FORMA DE PAGAMENTO DO ALUGUEL E ENCARGOS DA LOCAÇÃO</h2>\n{{#if (existe config.administradora_nome)}}\n<p>4.1. Os aluguéis e demais encargos da locação deverão ser pagos pela PARTE LOCATÁRIA até o dia {{aluguel.dia_vencimento}} ({{numeroExtenso aluguel.dia_vencimento}}) de cada mês vencido para {{config.administradora_nome}}{{#if (existe config.administradora_creci)}}, regularmente inscrita no CRECI sob nº {{config.administradora_creci}}{{/if}}{{#if (existe config.administradora_endereco)}}, com sede na {{config.administradora_endereco}}{{/if}}, empresa nomeada para exercer a administração da presente locação (doravante \"ADMINISTRADORA\").</p>\n{{else}}\n<p>4.1. Os aluguéis e demais encargos da locação deverão ser pagos pela PARTE LOCATÁRIA até o dia {{aluguel.dia_vencimento}} ({{numeroExtenso aluguel.dia_vencimento}}) de cada mês vencido, diretamente à PARTE LOCADORA ou a quem esta indicar.</p>\n{{/if}}\n<p>4.2. A PARTE LOCATÁRIA concorda com a cobrança dos aluguéis e encargos locatícios através de {{#if (existe config.meio_pagamento_texto)}}{{config.meio_pagamento_texto}}{{else}}boleto bancário{{/if}}, estabelecendo-se desde logo que o e-mail indicado no preâmbulo fica definido como endereço eletrônico para o recebimento dos boletos, sendo certo que qualquer alteração desse endereço deverá comunicar por escrito à PARTE LOCADORA.</p>\n<p>4.3. Na eventualidade de a PARTE LOCATÁRIA deixar de pagar o aluguel e demais encargos até a data do seu vencimento, o débito será acrescido de {{config.multa_atraso_percent}}% ({{numeroExtenso config.multa_atraso_percent}} por cento) a título de multa, fazendo-se o devido acréscimo, independentemente de qualquer procedimento judicial, à simples caracterização do atraso.</p>\n<p>4.4. Fica estabelecido que, em caso de mora da PARTE LOCATÁRIA no pagamento do aluguel e demais encargos, a importância devida vencerá juros de {{config.juros_mensais_atraso}}% ({{numeroExtenso config.juros_mensais_atraso}} por cento) ao mês, ficando igualmente sujeita à correção monetária que a lei admitir, se o atraso for superior a 30 (trinta) dias.</p>\n<p>4.5. Caso a entrega das chaves se dê antes do início do prazo contratual ajustado, serão cobrados da PARTE LOCATÁRIA os dias proporcionais de aluguel e encargos da locação, cujo vencimento será a data inicial do contrato, mantendo-se esta como data base, para todos os efeitos.</p>\n\n<h2>5. FINALIDADE</h2>\n<p>5.1. Ficará expressamente convencionado que o imóvel será utilizado pela PARTE LOCATÁRIA exclusivamente para uso residencial.</p>\n<p>5.2. A PARTE LOCATÁRIA não poderá transferir o presente contrato, nem tampouco sublocar ou emprestar o imóvel, no todo ou em parte, sem prévio consentimento por escrito da PARTE LOCADORA, devendo, no caso de este ser dado, agir oportunamente, junto aos ocupantes, no sentido de obter ao término do contrato, a total desocupação, de modo a assegurar a devolução do imóvel livre de coisas e pessoas.</p>\n<p>5.3. Em se tratando de imóvel de condomínio sujeito a regulamento interno, obriga-se, por si, seus prepostos e visitas, a respeitá-lo integralmente sob pena de rescisão contratual.</p>\n<p>5.3.1. Responsabiliza-se a PARTE LOCATÁRIA por eventuais multas decorrentes do descumprimento do regulamento interno, ainda que referida cobrança recaia sobre a PARTE LOCADORA.</p>\n<p>5.4. Fica expressamente vedada à PARTE LOCATÁRIA a alteração ou indicação do endereço do imóvel objeto do presente contrato como sede, filial, sucursal ou local de atendimento de qualquer pessoa jurídica de que sejam sócios ou qualquer outra, sob pena de caracterização de infração contratual passível de aplicação da multa prevista no item 7.1. e rescisão contratual.</p>\n\n<h2>6. ESTADO DO IMÓVEL E BENFEITORIAS</h2>\n<p>6.1. A PARTE LOCATÁRIA declara haver vistoriado o imóvel objeto do presente contrato, declarando-se ciente e aceitando-o no estado em que constatado no laudo de vistoria anexo - que passa a fazer parte integrante ao presente contrato, - obrigando-se a mantê-lo em perfeito estado de uso e conservação até o final da locação, notadamente no que diz respeito às instalações hidráulicas, elétricas e sanitárias, vidraças, fechaduras, esquadrias, pisos, portas, espelhos de interruptores de tomadas e demais acessórios, de modo que tudo seja restituído à PARTE LOCADORA.</p>\n<p>6.2. Caso o imóvel possua vícios aparentes anteriores à locação, assim entendidos aqueles que são de fácil constatação e que tenham sido identificados na vistoria inicial do imóvel, como por exemplo rachaduras em vidros e/ou ladrilhos, desgastes na pintura, falta de espelhos nas tomadas, falta de chaves em portas internas ou nos armários, a PARTE LOCADORA não estará obrigada a efetuar qualquer reparo, uma vez que o imóvel foi apresentado nestas condições à PARTE LOCATÁRIA, e o preço e demais condições do aluguel foram definidos considerando estes fatores. Por outro lado, a PARTE LOCATÁRIA também não estará obrigada a efetuar o reparo dos referidos vícios quando da devolução do imóvel, tendo em vista que assim o recebera da PARTE LOCADORA.</p>\n<p>6.3. A PARTE LOCATÁRIA obriga-se a manter em perfeitas condições de funcionamento e higiene todos os equipamentos eletroeletrônicos, sistemas de climatização (ar-condicionado), aquecedores a gás, bombas e demais instalações que guarnecem o imóvel.</p>\n<p>6.3.1. É de responsabilidade exclusiva da PARTE LOCATÁRIA a realização de manutenções preventivas e periódicas, conforme recomendação dos fabricantes ou normas técnicas vigentes, arcando integralmente com os custos de mão de obra e peças de reposição decorrentes do uso normal.</p>\n<p>6.3.2. No ato da rescisão contratual e entrega das chaves, a PARTE LOCATÁRIA deverá obrigatoriamente apresentar a PARTE LOCADORA ou à sua Administradora todos os comprovantes, notas fiscais e relatórios técnicos das manutenções realizadas durante o período de locação, bem como o comprovante da manutenção final de entrega.</p>\n<p>6.3.3. A ausência de comprovação das manutenções periódicas ou a entrega de equipamentos sem a devida revisão técnica autorizará a PARTE LOCADORA a realizar os reparos necessários, cujos custos serão repassados a PARTE LOCATÁRIA e/ou seus fiadores, sem prejuízo da aplicação de multa contratual por descumprimento de obrigação de zelo.</p>\n<p>6.4. Ao final da locação, considerar-se-ão incorporadas ao imóvel às benfeitorias eventualmente introduzidas pela PARTE LOCATÁRIA, sem que lhes assista o direito de retenção, ou a indenização qualquer, mesmo que tais benfeitorias possam ser consideradas úteis, ou necessárias.</p>\n<p>6.5. Obriga-se, porém, a PARTE LOCATÁRIA, a remover, por sua conta e às suas expensas, as benfeitorias que à PARTE LOCADORA não interessar.</p>\n<p>6.6. Qualquer benfeitoria a ser realizada pela PARTE LOCATÁRIA, seja necessária, útil ou voluptuária, somente poderá ser introduzida ao imóvel mediante autorização por escrito da PARTE LOCADORA.</p>\n<p>6.7. Quaisquer danos ocasionados ao imóvel e às instalações, bem como as despesas a que as PARTE LOCADORA for obrigada, em razão de eventuais modificações feitas no imóvel pela PARTE LOCATÁRIA, não ficam compreendidas na multa do item 7.1., mas serão ressarcidas à parte.</p>\n<p>6.8. A PARTE LOCATÁRIA desde já faculta à PARTE LOCADORA examinarem ou vistoriarem o imóvel, sempre que entender necessário, desde que se faça durante o horário comercial e mediante comunicação, com 24 (vinte e quatro) horas de antecedência.</p>\n\n<h2>7. MULTA</h2>\n<p>7.1. Fica estipulada a multa equivalente a {{config.multa_rescisoria_meses}} ({{numeroExtenso config.multa_rescisoria_meses}}) aluguéis vigentes na oportunidade da infração, para ser aplicada à parte que descumprir qualquer das cláusulas do presente contrato.</p>\n<p>7.2. Em caso de rescisão antecipada, na aplicação da multa prevista nesta cláusula, será observada a proporcionalidade prevista disposto do artigo 4º da Lei nº 8.245, de 18/10/91 (Lei do Inquilinato).</p>\n\n<h2>8. GARANTIA</h2>\n{{#if (eq garantia.tipo \"titulo_capitalizacao\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, a PARTE LOCATÁRIA, por ser de seu interesse, dá neste ato, em caução à PARTE LOCADORA o Título de Capitalização{{#if (gt garantia.titulo_valor 0)}} no valor nominal de {{moeda garantia.titulo_valor}} ({{extenso garantia.titulo_valor}}){{/if}}{{#if garantia.provider}} subscrito pela {{garantia.provider}}{{/if}}{{#if (existe garantia.titulo_proposta)}}, representado pela proposta/formulário n.º {{garantia.titulo_proposta}}{{/if}}.</p>\n<p>8.2. Ao término do prazo de vigência do Título, a PARTE LOCATÁRIA autoriza a {{#if garantia.provider}}{{garantia.provider}}{{else}}Sociedade de Capitalização{{/if}}, a REAPLICAR o valor de resgate, sempre em seu nome, dando origem a novo Título com as mesmas Condições Gerais dos Títulos inicialmente adquirido, sendo que este permanecerá como caução à locação supra referida até a efetiva desocupação do imóvel e entrega das chaves.</p>\n<p>8.3. A PARTE LOCATÁRIA se responsabiliza em comunicar qualquer alteração cadastral ou então se manifestar contrariamente à reaplicação do título, com no mínimo 15 (quinze) dias de antecedência da data do vencimento do título.</p>\n<p>8.4. Ao término do prazo de locação, desde que cumpridas pela PARTE LOCATÁRIA todas as obrigações decorrentes deste contrato, inclusive, a desocupação do imóvel e entrega das chaves sem a existência de qualquer débito, será liberado junto à {{#if garantia.provider}}{{garantia.provider}}{{else}}Sociedade de Capitalização{{/if}} a caução do(s) Título(s), apresentando(s). Para tanto, deverá ser apresentado documento rescisório da locação firmado pela PARTE LOCADORA e PARTE LOCATÁRIA, com o reconhecimento de firma das assinaturas, bem como outros documentos requeridos pela Sociedade de Capitalização.</p>\n<p>8.5. Se a PARTE LOCATÁRIA não observar quaisquer das cláusulas do presente contrato, fica, desde já, a PARTE LOCADORA autorizada a resgatar o(s) Título(s) caucionado(s), a qualquer momento, mesmo antes do prazo final de capitalização, inclusive com a correção devida, independentemente de interpelação judicial ou extrajudicial, a fim de que o valor do resgate quite eventual importância que lhe seja devida em razão de débitos oriundos deste contrato, respeitando os termos descritos nas condições gerais do título de capitalização.</p>\n<p>8.6. Se por acaso a PARTE LOCATÁRIA contestar o valor apresentado e ajuizar a competente ação cautelar de prestação de contas, correrão por conta dos mesmos todas as despesas consequentes, inclusive custas e honorários advocatícios.</p>\n{{else if (eq garantia.tipo \"fiador\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, o(a) FIADOR(A) qualificado(a) no preâmbulo assume responsabilidade solidária com a PARTE LOCATÁRIA, com expressa renúncia ao benefício de ordem (arts. 827 e 838 do Código Civil), respondendo até a efetiva entrega das chaves, ainda que a locação se prorrogue por prazo indeterminado.</p>\n{{else if (eq garantia.tipo \"caucao\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, a PARTE LOCATÁRIA dá neste ato, a título de caução, o equivalente a {{garantia.caucao_meses}} ({{numeroExtenso garantia.caucao_meses}}) aluguéis, nos termos do art. 38 da Lei nº 8.245/91, a ser restituído ao final da locação, deduzidos eventuais débitos e danos apurados em vistoria.</p>\n{{else if (eq garantia.tipo \"seguro_fianca\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, a locação é garantida por seguro de fiança locatícia{{#if garantia.provider}} contratado junto a {{garantia.provider}}{{/if}}{{#if (gt garantia.cobertura_meses 0)}}, com cobertura de {{garantia.cobertura_meses}} ({{numeroExtenso garantia.cobertura_meses}}) meses de aluguel{{/if}}, cujas condições e apólice integram este contrato.</p>\n{{else if (eq garantia.tipo \"garantia_digital\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, a locação é garantida por garantia locatícia{{#if garantia.provider}} prestada por {{garantia.provider}}{{/if}}{{#if (gt garantia.cobertura_meses 0)}}, com cobertura de {{garantia.cobertura_meses}} ({{numeroExtenso garantia.cobertura_meses}}) meses de aluguel{{/if}}, na forma do respectivo termo de adesão, que integra este contrato.</p>\n{{else if (eq garantia.tipo \"sem_garantia\")}}\n<p>8.1. As partes ajustam a presente locação sem modalidade de garantia, nos termos do art. 37 da Lei nº 8.245/91.</p>\n{{else}}\n<p>8.1. A locação é garantida na modalidade ajustada entre as partes, observado o art. 37 da Lei nº 8.245/91.</p>\n{{/if}}\n\n<h2>9. ENCARGOS DA LOCAÇÃO E SEGURO CONTRA INCÊNDIO</h2>\n<p>9.1. Correrão por conta exclusiva da PARTE LOCATÁRIA, os pagamentos da integralidade dos impostos e taxas que sobre o imóvel recaem ou venham a recair, respondendo ainda, a PARTE LOCATÁRIA, pela totalidade das despesas decorrentes do consumo de energia, água (se houver), gás (se houver) e IPTU, qualquer que seja a forma da respectiva cobrança.</p>\n<p>9.1.1. Compromete-se a PARTE LOCATÁRIA a entregar à PARTE LOCADORA a \"notificação de lançamento\" do IPTU.</p>\n{{#if (existe config.administradora_nome)}}\n<p>9.1.2. Os valores correspondentes ao IPTU{{#if (gt aluguel.iptu_mensal 0)}} ({{moeda aluguel.iptu_mensal}} por mês – valor de referência){{/if}} e despesas ordinárias de condomínio{{#if (gt aluguel.condominio_mensal 0)}} ({{moeda aluguel.condominio_mensal}} – valor de referência){{/if}}, são de responsabilidade da PARTE LOCATÁRIA e serão lançados pela ADMINISTRADORA, juntamente com o valor do aluguel, no mesmo boleto, devendo ser efetuado o respectivo pagamento na data do vencimento do aluguel.{{#if (gt aluguel.encargos 0)}} O total dos encargos mensais lançados no boleto, na data de assinatura deste contrato, é de {{moeda aluguel.encargos}}, sujeito a alteração conforme os lançamentos do condomínio e do Município.{{/if}}</p>\n<p>9.1.3. A PARTE LOCATÁRIA declara-se ciente de que o IPTU e despesas ordinárias de condomínio são pagos a vencer, ao contrário do aluguel que será pago vencido, declarando-se ciente também que antes do vencimento do primeiro mês de locação haverá a cobrança desse encargo.</p>\n{{/if}}\n<p>9.2. A PARTE LOCATÁRIA será responsável ainda pelo pagamento de todas as despesas, multas e demais sanções decorrentes do mau uso do imóvel e ou eventual retenção dos avisos de impostos, taxas e demais encargos públicos que incidem ou vierem incidir sobre o mesmo.</p>\n<p>9.3. A PARTE LOCATÁRIA se compromete, sempre que solicitado e na ocasião da entrega das chaves do imóvel, a apresentar as 03 (três) últimas contas quitadas da ENEL, SABESP (se houver) e COMGÁS (se houver).</p>\n<p>9.3.1. Compromete-se ainda a PARTE LOCATÁRIA por sua conta e suas expensas, providenciar a transferência para seu nome das contas de consumo de energia, água (se houver) e gás (se houver) junto às respectivas concessionárias no prazo de até 30 (trinta) dias da assinatura do presente contrato.</p>\n<p>9.3.2. Ao final da locação e na oportunidade da entrega das chaves obriga-se a PARTE LOCATÁRIA a apresentar também o comprovante de solicitação de suspensão dos serviços de fornecimento de energia, água (se houver) e gás (se houver) junto às respectivas concessionárias.</p>\n<p>9.4. A PARTE LOCATÁRIA se compromete a efetuar seguro contra incêndio de todo do imóvel no valor de 100 (cem) vezes o valor do aluguel, que deverá ser periodicamente reajustado, de sorte a se manter atualizado, emitindo-se a apólice em favor da PARTE LOCADORA, em cujo poder ficará para que, no caso de sinistro, possam os mesmos reconstruir o imóvel, facultado à PARTE LOCATÁRIA reocupá-lo, terminada a obra, pelo tempo que restar a locação.</p>\n\n<h2>10 - CONDIÇÕES GERAIS</h2>\n<p>10.1. Na hipótese de o imóvel sofrer desapropriação, estará o presente contrato rescindido a partir da citação para a ação expropriatória, sendo certo que caberá à PARTE LOCADORA receber o valor da indenização, podendo a PARTE LOCATÁRIA, se assim entender, promover, contra o órgão expropriante, a ação de indenização a que porventura tiver direito.</p>\n<p>10.1.1. A rescisão deste contrato, na hipótese prevista nesta cláusula, não obrigará nenhuma das partes a indenizar a outra.</p>\n<p>10.1.2. Os aluguéis serão contados até a data da efetiva desocupação e entrega das chaves do imóvel à PARTE LOCADORA.</p>\n<p>10.2. Tudo quanto for devido, em razão deste contrato, e que não comporte processo executivo, será cobrado em ação competente, respondendo o devedor, em qualquer hipótese, pelos honorários advocatícios fixados em 20% (vinte por cento) sobre o valor do débito que o credor constituir para o patrocínio dos seus direitos.</p>\n<p>10.3. Obriga-se a PARTE LOCATÁRIA a não praticar e proibir a prática, dentro dos limites do imóvel locado, de atos contrários aos bons costumes, à moral, e a perturbação da vizinhança, além de zelarem e efetuarem as suas expensas, pela manutenção, asseio e conservação das instalações e dependências do imóvel objeto da presente locação, inclusive quanto aos reparos e obras a serem realizadas, oriundas de exigências formuladas pelo Poder Público.</p>\n<p>10.4. A PARTE LOCATÁRIA autoriza proceder sua citação inicial, interpelações, intimações, notificações, ou qualquer outro ato de comunicação processual, mediante correspondência com AR/MP (aviso de recebimento), ou mensagem enviada ao endereço eletrônico indicado no preâmbulo, ou ainda, sendo necessário, pelas demais formas previstas no Código de Processo Civil, em toda e qualquer ação judicial ou procedimento extrajudicial, decorrentes da relação locatícia ora ajustada, especialmente as intimações referidas nos artigos 62, inciso III e 67 incisos II e VII da lei 8.245/91.</p>\n<p>10.5. Quaisquer questões oriundas do presente contrato serão dirimidas no Foro {{#if (existe config.foro_texto)}}da comarca de {{config.foro_texto}}{{else}}da comarca de localização do imóvel{{/if}}, eleito pelas partes como o único competente para tal, com renúncia a qualquer outro, por mais privilegiado que seja ou possa vir a ser.</p>\n\n<p>E por estarem justos e acertados, assinam este instrumento, em 03 (três) vias de igual teor e forma, na presença de duas testemunhas abaixo nomeadas.</p>\n\n<p style=\"margin-top: 24pt;\">{{#if (existe config.municipio_imovel)}}{{config.municipio_imovel}}, {{/if}}{{#if (existe config.data_assinatura)}}{{dataExtenso config.data_assinatura}}{{/if}}.</p>\n\n{{#each locatarios}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{else}}{{this.razao_social}}{{/if}}<br>PARTE LOCATÁRIA</p>\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{this.conjuge.nome}}<br>CÔNJUGE DA PARTE LOCATÁRIA</p>\n{{/if}}{{/if}}\n{{/each}}\n\n{{#each locadores}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{else}}{{this.razao_social}}{{/if}}<br>PARTE LOCADORA</p>\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{this.conjuge.nome}}<br>CÔNJUGE DA PARTE LOCADORA</p>\n{{/if}}{{/if}}\n{{/each}}\n\n{{#if (eq garantia.tipo \"fiador\")}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{#if (eq garantia.fiador.tipo_pessoa \"juridica\")}}{{garantia.fiador.razao_social}}{{else}}{{garantia.fiador.nome}}{{/if}}<br>FIADOR(A)</p>\n{{#if garantia.fiador.conjuge.nome}}{{#if (temConjuge garantia.fiador.estado_civil)}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{garantia.fiador.conjuge.nome}}<br>CÔNJUGE DO(A) FIADOR(A)</p>\n{{/if}}{{/if}}\n{{/if}}\n\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>Nome:<br>CPF:<br>Testemunha</p>\n\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>Nome:<br>CPF:<br>Testemunha</p>\n\n<!-- CLAUSE_SLOT:LOC -->\n\n</div>\n",
  "locacao_comercial_v3.hbs": "<div class=\"contrato\">\n\n<h1>INSTRUMENTO PARTICULAR DE CONTRATO DE LOCAÇÃO DE IMÓVEL PARA FINS NÃO RESIDENCIAIS</h1>\n\n<p>Pelo presente instrumento particular de contrato de locação, de um lado, como LOCADOR(A) e doravante nomeada PARTE LOCADORA, {{#each locadores}}{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{#if (existe this.nacionalidade)}}, {{this.nacionalidade}}{{/if}}{{#if (existe this.estado_civil)}}, {{this.estado_civil}}{{/if}}{{#if (existe this.profissao)}}, {{this.profissao}}{{/if}}{{#if (existe this.rg)}}, portador(a) da cédula de identidade RG nº {{this.rg}}{{/if}}{{#if (existe this.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.cpf}}{{/if}}{{#if (existe this.endereco)}}, residente e domiciliado(a) na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if (existe this.email)}}, endereço eletrônico e-mail {{this.email}}{{/if}}{{else}}{{this.razao_social}}, pessoa jurídica de direito privado, inscrita no CNPJ/MF sob nº {{cnpj this.cnpj}}{{#if (existe this.endereco)}}, com sede na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if this.representante.nome}}, neste ato representada por {{this.representante.nome}}, inscrito(a) no CPF/MF sob nº {{cpf this.representante.cpf}}{{/if}}{{/if}}{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}, casado(a) com {{this.conjuge.nome}}{{#if (existe this.conjuge.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.conjuge.cpf}}{{/if}}{{/if}}{{/if}}{{#unless @last}}; {{/unless}}{{/each}}, e de outro lado, como LOCATÁRIO(A) e doravante nomeada PARTE LOCATÁRIA, {{#each locatarios}}{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{#if (existe this.nacionalidade)}}, {{this.nacionalidade}}{{/if}}{{#if (existe this.estado_civil)}}, {{this.estado_civil}}{{/if}}{{#if (existe this.profissao)}}, {{this.profissao}}{{/if}}{{#if (existe this.rg)}}, portador(a) da cédula de identidade RG nº {{this.rg}}{{/if}}{{#if (existe this.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.cpf}}{{/if}}{{#if (existe this.endereco)}}, residente e domiciliado(a) na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if (existe this.email)}}, endereço eletrônico e-mail {{this.email}}{{/if}}{{else}}{{this.razao_social}}, pessoa jurídica de direito privado, inscrita no CNPJ/MF sob nº {{cnpj this.cnpj}}{{#if (existe this.endereco)}}, com sede na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if this.representante.nome}}, neste ato representada por {{this.representante.nome}}, inscrito(a) no CPF/MF sob nº {{cpf this.representante.cpf}}{{/if}}{{/if}}{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}, casado(a) com {{this.conjuge.nome}}{{#if (existe this.conjuge.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.conjuge.cpf}}{{/if}}{{/if}}{{/if}}{{#unless @last}}; {{/unless}}{{/each}}{{#if (eq garantia.tipo \"fiador\")}}, e, na qualidade de FIADOR(A), {{#if (eq garantia.fiador.tipo_pessoa \"juridica\")}}{{garantia.fiador.razao_social}}, pessoa jurídica de direito privado, inscrita no CNPJ/MF sob nº {{cnpj garantia.fiador.cnpj}}{{#if (existe garantia.fiador.endereco)}}, com sede na {{garantia.fiador.endereco}}, nº {{garantia.fiador.numero}}{{#if garantia.fiador.bairro}}, {{garantia.fiador.bairro}}{{/if}}{{#if (existe garantia.fiador.cep)}}, CEP {{cep garantia.fiador.cep}}{{/if}}{{#if (existe garantia.fiador.cidade)}}, {{garantia.fiador.cidade}}/{{garantia.fiador.uf}}{{/if}}{{/if}}{{#if garantia.fiador.representante.nome}}, neste ato representada por {{garantia.fiador.representante.nome}}, inscrito(a) no CPF/MF sob nº {{cpf garantia.fiador.representante.cpf}}{{/if}}{{else}}{{garantia.fiador.nome}}{{#if (existe garantia.fiador.nacionalidade)}}, {{garantia.fiador.nacionalidade}}{{/if}}{{#if (existe garantia.fiador.estado_civil)}}, {{garantia.fiador.estado_civil}}{{/if}}{{#if (existe garantia.fiador.rg)}}, portador(a) da cédula de identidade RG nº {{garantia.fiador.rg}}{{/if}}{{#if (existe garantia.fiador.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf garantia.fiador.cpf}}{{/if}}{{#if (existe garantia.fiador.endereco)}}, residente e domiciliado(a) na {{garantia.fiador.endereco}}, nº {{garantia.fiador.numero}}, {{garantia.fiador.cidade}}/{{garantia.fiador.uf}}{{/if}}{{/if}}{{/if}}, têm entre si, justo e acertado o seguinte:</p>\n\n<h2>1. IMÓVEL</h2>\n<p>1.1. A PARTE LOCADORA, proprietária do(a) {{#if (existe imovel.tipo_texto)}}{{imovel.tipo_texto}}{{else}}{{imovel.kind}}{{/if}}{{#if (existe imovel.complemento)}} {{imovel.complemento}}{{/if}}{{#if (existe imovel.condominio_nome)}}, do {{imovel.condominio_nome}}{{/if}}{{#if (existe imovel.rua)}}, localizado(a) na {{imovel.rua}}{{#if (existe imovel.numero)}}, nº {{imovel.numero}}{{/if}}{{/if}}{{#if imovel.bairro}}, {{imovel.bairro}}{{/if}}{{#if (existe imovel.cep)}}, CEP {{cep imovel.cep}}{{/if}}{{#if (existe imovel.cidade)}}, {{imovel.cidade}}{{#if (existe imovel.uf)}}/{{imovel.uf}}{{/if}}{{/if}}{{#if (gt imovel.area 0)}}, com área de {{numero imovel.area}} m²{{/if}}{{#if (gt imovel.vagas_garagem 0)}}, com {{imovel.vagas_garagem}} ({{numeroExtenso imovel.vagas_garagem \"f\"}}) vaga(s) de garagem{{/if}}{{#if imovel.inscricao_iptu}}, regularmente cadastrado na Prefeitura Municipal de {{imovel.cidade}} pelo contribuinte nº {{imovel.inscricao_iptu}}{{/if}}{{#if imovel.matricula}}, objeto da matrícula nº {{imovel.matricula}}{{#if imovel.cartorio}} do {{imovel.cartorio}}{{/if}}{{/if}}, pelo presente e na melhor forma de direito, loca-o à PARTE LOCATÁRIA, mediante as cláusulas e condições seguintes.</p>\n<p>1.2. Descrição do imóvel: {{imovel.descricao}}</p>\n\n<h2>2. PRAZO</h2>\n<p>2.1. O prazo de locação é de {{aluguel.vigencia_meses}} ({{numeroExtenso aluguel.vigencia_meses}}) meses{{#if (existe config.vigencia_inicio_texto)}}, a contar de {{config.vigencia_inicio_texto}}{{/if}}{{#if (existe config.vigencia_fim_texto)}} e com término fixado em {{config.vigencia_fim_texto}}{{/if}}, data em que a PARTE LOCATÁRIA se compromete a devolver o imóvel completamente livre e desocupado de coisas e pessoas.</p>\n<p>2.1.1. Findo o prazo estipulado, se a PARTE LOCATÁRIA permanecer no imóvel por mais de 30 (trinta) dias sem oposição da PARTE LOCADORA, presumir-se-á prorrogada a locação nas condições ajustadas, passando o contrato a vigorar por prazo indeterminado, nos termos do art. 56, parágrafo único, da Lei nº 8.245/91.</p>\n<p>2.1.2. Para a devolução do imóvel e entrega das chaves, por qualquer motivo que seja, mesmo que por término do contrato, ou após, se a locação se prorrogar por prazo indeterminado, obriga-se a PARTE LOCATÁRIA a notificar por escrito a PARTE LOCADORA com antecedência mínima de 30 (trinta) dias da desocupação.</p>\n\n<h2>3. ALUGUEL</h2>\n<p>3.1. O valor do aluguel mensal é de {{moeda aluguel.valor}} ({{extenso aluguel.valor}}) que se corrigirá a cada 12 (doze) meses, {{#if (eq aluguel.indice_reajuste \"IGPM\")}}pelo Índice Geral de Preços - Mercado (IGP-M){{else if (eq aluguel.indice_reajuste \"IPCA\")}}pelo Índice Nacional de Preços ao Consumidor Amplo (IPCA){{else}}pelo índice ajustado entre as partes{{/if}} pelo tempo que perdurar a locação, ou o índice que, em sua substituição, for eventualmente imposto.</p>\n<p>3.2. Não se aplica ao presente contrato para fins de reajuste do valor locativo, a variação negativa do índice indicado para medir a inflação no período.</p>\n\n<h2>4. FORMA DE PAGAMENTO DO ALUGUEL E ENCARGOS DA LOCAÇÃO</h2>\n{{#if (existe config.administradora_nome)}}\n<p>4.1. Os aluguéis e demais encargos da locação deverão ser pagos pela PARTE LOCATÁRIA até o dia {{aluguel.dia_vencimento}} ({{numeroExtenso aluguel.dia_vencimento}}) de cada mês vencido para {{config.administradora_nome}}{{#if (existe config.administradora_creci)}}, regularmente inscrita no CRECI sob nº {{config.administradora_creci}}{{/if}}{{#if (existe config.administradora_endereco)}}, com sede na {{config.administradora_endereco}}{{/if}}, empresa nomeada para exercer a administração da presente locação (doravante \"ADMINISTRADORA\").</p>\n{{else}}\n<p>4.1. Os aluguéis e demais encargos da locação deverão ser pagos pela PARTE LOCATÁRIA até o dia {{aluguel.dia_vencimento}} ({{numeroExtenso aluguel.dia_vencimento}}) de cada mês vencido, diretamente à PARTE LOCADORA ou a quem esta indicar.</p>\n{{/if}}\n<p>4.2. A PARTE LOCATÁRIA concorda com a cobrança dos aluguéis e encargos locatícios através de {{#if (existe config.meio_pagamento_texto)}}{{config.meio_pagamento_texto}}{{else}}boleto bancário{{/if}}, estabelecendo-se desde logo que o e-mail indicado no preâmbulo fica definido como endereço eletrônico para o recebimento dos boletos, sendo certo que qualquer alteração desse endereço deverá comunicar por escrito à PARTE LOCADORA.</p>\n<p>4.3. Na eventualidade de a PARTE LOCATÁRIA deixar de pagar o aluguel e demais encargos até a data do seu vencimento, o débito será acrescido de {{config.multa_atraso_percent}}% ({{numeroExtenso config.multa_atraso_percent}} por cento) a título de multa, fazendo-se o devido acréscimo, independentemente de qualquer procedimento judicial, à simples caracterização do atraso.</p>\n<p>4.4. Fica estabelecido que, em caso de mora da PARTE LOCATÁRIA no pagamento do aluguel e demais encargos, a importância devida vencerá juros de {{config.juros_mensais_atraso}}% ({{numeroExtenso config.juros_mensais_atraso}} por cento) ao mês, ficando igualmente sujeita à correção monetária que a lei admitir, se o atraso for superior a 30 (trinta) dias.</p>\n<p>4.5. Caso a entrega das chaves se dê antes do início do prazo contratual ajustado, serão cobrados da PARTE LOCATÁRIA os dias proporcionais de aluguel e encargos da locação, cujo vencimento será a data inicial do contrato, mantendo-se esta como data base, para todos os efeitos.</p>\n\n<h2>5. FINALIDADE</h2>\n<p>5.1. Ficará expressamente convencionado que o imóvel será utilizado pela PARTE LOCATÁRIA exclusivamente para o exercício da atividade de {{#if (existe imovel.destinacao)}}{{imovel.destinacao}}{{else}}fins comerciais{{/if}}, vedada a alteração da destinação sem prévio consentimento por escrito da PARTE LOCADORA, observado o art. 13 da Lei nº 8.245/91.</p>\n<p>5.2. A PARTE LOCATÁRIA não poderá transferir o presente contrato, nem tampouco sublocar ou emprestar o imóvel, no todo ou em parte, sem prévio consentimento por escrito da PARTE LOCADORA, devendo, no caso de este ser dado, agir oportunamente, junto aos ocupantes, no sentido de obter ao término do contrato, a total desocupação, de modo a assegurar a devolução do imóvel livre de coisas e pessoas.</p>\n<p>5.3. Em se tratando de imóvel de condomínio sujeito a regulamento interno, obriga-se, por si, seus prepostos e visitas, a respeitá-lo integralmente sob pena de rescisão contratual.</p>\n<p>5.3.1. Responsabiliza-se a PARTE LOCATÁRIA por eventuais multas decorrentes do descumprimento do regulamento interno, ainda que referida cobrança recaia sobre a PARTE LOCADORA.</p>\n<p>5.4. A PARTE LOCATÁRIA obriga-se a obter e manter, às suas expensas, todas as licenças, alvarás e autorizações necessárias ao exercício de sua atividade no imóvel, respondendo por eventuais infrações administrativas.</p>\n\n<h2>6. ESTADO DO IMÓVEL E BENFEITORIAS</h2>\n<p>6.1. A PARTE LOCATÁRIA declara haver vistoriado o imóvel objeto do presente contrato, declarando-se ciente e aceitando-o no estado em que constatado no laudo de vistoria anexo - que passa a fazer parte integrante ao presente contrato, - obrigando-se a mantê-lo em perfeito estado de uso e conservação até o final da locação, notadamente no que diz respeito às instalações hidráulicas, elétricas e sanitárias, vidraças, fechaduras, esquadrias, pisos, portas, espelhos de interruptores de tomadas e demais acessórios, de modo que tudo seja restituído à PARTE LOCADORA.</p>\n<p>6.2. Caso o imóvel possua vícios aparentes anteriores à locação, assim entendidos aqueles que são de fácil constatação e que tenham sido identificados na vistoria inicial do imóvel, como por exemplo rachaduras em vidros e/ou ladrilhos, desgastes na pintura, falta de espelhos nas tomadas, falta de chaves em portas internas ou nos armários, a PARTE LOCADORA não estará obrigada a efetuar qualquer reparo, uma vez que o imóvel foi apresentado nestas condições à PARTE LOCATÁRIA, e o preço e demais condições do aluguel foram definidos considerando estes fatores. Por outro lado, a PARTE LOCATÁRIA também não estará obrigada a efetuar o reparo dos referidos vícios quando da devolução do imóvel, tendo em vista que assim o recebera da PARTE LOCADORA.</p>\n<p>6.3. A PARTE LOCATÁRIA obriga-se a manter em perfeitas condições de funcionamento e higiene todos os equipamentos eletroeletrônicos, sistemas de climatização (ar-condicionado), aquecedores a gás, bombas e demais instalações que guarnecem o imóvel.</p>\n<p>6.3.1. É de responsabilidade exclusiva da PARTE LOCATÁRIA a realização de manutenções preventivas e periódicas, conforme recomendação dos fabricantes ou normas técnicas vigentes, arcando integralmente com os custos de mão de obra e peças de reposição decorrentes do uso normal.</p>\n<p>6.3.2. No ato da rescisão contratual e entrega das chaves, a PARTE LOCATÁRIA deverá obrigatoriamente apresentar a PARTE LOCADORA ou à sua Administradora todos os comprovantes, notas fiscais e relatórios técnicos das manutenções realizadas durante o período de locação, bem como o comprovante da manutenção final de entrega.</p>\n<p>6.3.3. A ausência de comprovação das manutenções periódicas ou a entrega de equipamentos sem a devida revisão técnica autorizará a PARTE LOCADORA a realizar os reparos necessários, cujos custos serão repassados a PARTE LOCATÁRIA e/ou seus fiadores, sem prejuízo da aplicação de multa contratual por descumprimento de obrigação de zelo.</p>\n<p>6.4. As obras de adaptação do imóvel à atividade da PARTE LOCATÁRIA dependem de autorização prévia e escrita da PARTE LOCADORA. Ao final da locação, considerar-se-ão incorporadas ao imóvel às benfeitorias eventualmente introduzidas pela PARTE LOCATÁRIA, sem que lhes assista o direito de retenção, ou a indenização qualquer, mesmo que tais benfeitorias possam ser consideradas úteis, ou necessárias.</p>\n<p>6.5. Obriga-se, porém, a PARTE LOCATÁRIA, a remover, por sua conta e às suas expensas, as benfeitorias que à PARTE LOCADORA não interessar.</p>\n<p>6.6. Qualquer benfeitoria a ser realizada pela PARTE LOCATÁRIA, seja necessária, útil ou voluptuária, somente poderá ser introduzida ao imóvel mediante autorização por escrito da PARTE LOCADORA.</p>\n<p>6.7. Quaisquer danos ocasionados ao imóvel e às instalações, bem como as despesas a que as PARTE LOCADORA for obrigada, em razão de eventuais modificações feitas no imóvel pela PARTE LOCATÁRIA, não ficam compreendidas na multa do item 7.1., mas serão ressarcidas à parte.</p>\n<p>6.8. A PARTE LOCATÁRIA desde já faculta à PARTE LOCADORA examinarem ou vistoriarem o imóvel, sempre que entender necessário, desde que se faça durante o horário comercial e mediante comunicação, com 24 (vinte e quatro) horas de antecedência.</p>\n\n<h2>7. MULTA</h2>\n<p>7.1. Fica estipulada a multa equivalente a {{config.multa_rescisoria_meses}} ({{numeroExtenso config.multa_rescisoria_meses}}) aluguéis vigentes na oportunidade da infração, para ser aplicada à parte que descumprir qualquer das cláusulas do presente contrato.</p>\n<p>7.2. Em caso de rescisão antecipada, na aplicação da multa prevista nesta cláusula, será observada a proporcionalidade prevista disposto do artigo 4º da Lei nº 8.245, de 18/10/91 (Lei do Inquilinato).</p>\n\n<h2>8. GARANTIA</h2>\n{{#if (eq garantia.tipo \"titulo_capitalizacao\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, a PARTE LOCATÁRIA, por ser de seu interesse, dá neste ato, em caução à PARTE LOCADORA o Título de Capitalização{{#if (gt garantia.titulo_valor 0)}} no valor nominal de {{moeda garantia.titulo_valor}} ({{extenso garantia.titulo_valor}}){{/if}}{{#if garantia.provider}} subscrito pela {{garantia.provider}}{{/if}}{{#if (existe garantia.titulo_proposta)}}, representado pela proposta/formulário n.º {{garantia.titulo_proposta}}{{/if}}.</p>\n<p>8.2. Ao término do prazo de vigência do Título, a PARTE LOCATÁRIA autoriza a {{#if garantia.provider}}{{garantia.provider}}{{else}}Sociedade de Capitalização{{/if}}, a REAPLICAR o valor de resgate, sempre em seu nome, dando origem a novo Título com as mesmas Condições Gerais dos Títulos inicialmente adquirido, sendo que este permanecerá como caução à locação supra referida até a efetiva desocupação do imóvel e entrega das chaves.</p>\n<p>8.3. A PARTE LOCATÁRIA se responsabiliza em comunicar qualquer alteração cadastral ou então se manifestar contrariamente à reaplicação do título, com no mínimo 15 (quinze) dias de antecedência da data do vencimento do título.</p>\n<p>8.4. Ao término do prazo de locação, desde que cumpridas pela PARTE LOCATÁRIA todas as obrigações decorrentes deste contrato, inclusive, a desocupação do imóvel e entrega das chaves sem a existência de qualquer débito, será liberado junto à {{#if garantia.provider}}{{garantia.provider}}{{else}}Sociedade de Capitalização{{/if}} a caução do(s) Título(s), apresentando(s). Para tanto, deverá ser apresentado documento rescisório da locação firmado pela PARTE LOCADORA e PARTE LOCATÁRIA, com o reconhecimento de firma das assinaturas, bem como outros documentos requeridos pela Sociedade de Capitalização.</p>\n<p>8.5. Se a PARTE LOCATÁRIA não observar quaisquer das cláusulas do presente contrato, fica, desde já, a PARTE LOCADORA autorizada a resgatar o(s) Título(s) caucionado(s), a qualquer momento, mesmo antes do prazo final de capitalização, inclusive com a correção devida, independentemente de interpelação judicial ou extrajudicial, a fim de que o valor do resgate quite eventual importância que lhe seja devida em razão de débitos oriundos deste contrato, respeitando os termos descritos nas condições gerais do título de capitalização.</p>\n<p>8.6. Se por acaso a PARTE LOCATÁRIA contestar o valor apresentado e ajuizar a competente ação cautelar de prestação de contas, correrão por conta dos mesmos todas as despesas consequentes, inclusive custas e honorários advocatícios.</p>\n{{else if (eq garantia.tipo \"fiador\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, o(a) FIADOR(A) qualificado(a) no preâmbulo assume responsabilidade solidária com a PARTE LOCATÁRIA, com expressa renúncia ao benefício de ordem (arts. 827 e 838 do Código Civil), respondendo até a efetiva entrega das chaves, ainda que a locação se prorrogue por prazo indeterminado.</p>\n{{else if (eq garantia.tipo \"caucao\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, a PARTE LOCATÁRIA dá neste ato, a título de caução, o equivalente a {{garantia.caucao_meses}} ({{numeroExtenso garantia.caucao_meses}}) aluguéis, nos termos do art. 38 da Lei nº 8.245/91, a ser restituído ao final da locação, deduzidos eventuais débitos e danos apurados em vistoria.</p>\n{{else if (eq garantia.tipo \"seguro_fianca\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, a locação é garantida por seguro de fiança locatícia{{#if garantia.provider}} contratado junto a {{garantia.provider}}{{/if}}{{#if (gt garantia.cobertura_meses 0)}}, com cobertura de {{garantia.cobertura_meses}} ({{numeroExtenso garantia.cobertura_meses}}) meses de aluguel{{/if}}, cujas condições e apólice integram este contrato.</p>\n{{else if (eq garantia.tipo \"garantia_digital\")}}\n<p>8.1. Para garantir as obrigações assumidas neste contrato, a locação é garantida por garantia locatícia{{#if garantia.provider}} prestada por {{garantia.provider}}{{/if}}{{#if (gt garantia.cobertura_meses 0)}}, com cobertura de {{garantia.cobertura_meses}} ({{numeroExtenso garantia.cobertura_meses}}) meses de aluguel{{/if}}, na forma do respectivo termo de adesão, que integra este contrato.</p>\n{{else if (eq garantia.tipo \"sem_garantia\")}}\n<p>8.1. As partes ajustam a presente locação sem modalidade de garantia, nos termos do art. 37 da Lei nº 8.245/91.</p>\n{{else}}\n<p>8.1. A locação é garantida na modalidade ajustada entre as partes, observado o art. 37 da Lei nº 8.245/91.</p>\n{{/if}}\n\n<h2>9. ENCARGOS DA LOCAÇÃO E SEGURO CONTRA INCÊNDIO</h2>\n<p>9.1. Correrão por conta exclusiva da PARTE LOCATÁRIA, os pagamentos da integralidade dos impostos e taxas que sobre o imóvel recaem ou venham a recair, inclusive taxas de funcionamento e alvarás, respondendo ainda, a PARTE LOCATÁRIA, pela totalidade das despesas decorrentes do consumo de energia, água (se houver), gás (se houver) e IPTU, qualquer que seja a forma da respectiva cobrança.</p>\n<p>9.1.1. Compromete-se a PARTE LOCATÁRIA a entregar à PARTE LOCADORA a \"notificação de lançamento\" do IPTU.</p>\n{{#if (existe config.administradora_nome)}}\n<p>9.1.2. Os valores correspondentes ao IPTU{{#if (gt aluguel.iptu_mensal 0)}} ({{moeda aluguel.iptu_mensal}} por mês – valor de referência){{/if}} e despesas ordinárias de condomínio{{#if (gt aluguel.condominio_mensal 0)}} ({{moeda aluguel.condominio_mensal}} – valor de referência){{/if}}, são de responsabilidade da PARTE LOCATÁRIA e serão lançados pela ADMINISTRADORA, juntamente com o valor do aluguel, no mesmo boleto, devendo ser efetuado o respectivo pagamento na data do vencimento do aluguel.{{#if (gt aluguel.encargos 0)}} O total dos encargos mensais lançados no boleto, na data de assinatura deste contrato, é de {{moeda aluguel.encargos}}, sujeito a alteração conforme os lançamentos do condomínio e do Município.{{/if}}</p>\n<p>9.1.3. A PARTE LOCATÁRIA declara-se ciente de que o IPTU e despesas ordinárias de condomínio são pagos a vencer, ao contrário do aluguel que será pago vencido, declarando-se ciente também que antes do vencimento do primeiro mês de locação haverá a cobrança desse encargo.</p>\n{{/if}}\n<p>9.2. A PARTE LOCATÁRIA será responsável ainda pelo pagamento de todas as despesas, multas e demais sanções decorrentes do mau uso do imóvel e ou eventual retenção dos avisos de impostos, taxas e demais encargos públicos que incidem ou vierem incidir sobre o mesmo.</p>\n<p>9.3. A PARTE LOCATÁRIA se compromete, sempre que solicitado e na ocasião da entrega das chaves do imóvel, a apresentar as 03 (três) últimas contas quitadas da ENEL, SABESP (se houver) e COMGÁS (se houver).</p>\n<p>9.3.1. Compromete-se ainda a PARTE LOCATÁRIA por sua conta e suas expensas, providenciar a transferência para seu nome das contas de consumo de energia, água (se houver) e gás (se houver) junto às respectivas concessionárias no prazo de até 30 (trinta) dias da assinatura do presente contrato.</p>\n<p>9.3.2. Ao final da locação e na oportunidade da entrega das chaves obriga-se a PARTE LOCATÁRIA a apresentar também o comprovante de solicitação de suspensão dos serviços de fornecimento de energia, água (se houver) e gás (se houver) junto às respectivas concessionárias.</p>\n<p>9.4. A PARTE LOCATÁRIA se compromete a efetuar seguro contra incêndio de todo do imóvel no valor de 100 (cem) vezes o valor do aluguel, que deverá ser periodicamente reajustado, de sorte a se manter atualizado, emitindo-se a apólice em favor da PARTE LOCADORA, em cujo poder ficará para que, no caso de sinistro, possam os mesmos reconstruir o imóvel, facultado à PARTE LOCATÁRIA reocupá-lo, terminada a obra, pelo tempo que restar a locação.</p>\n\n<h2>10. AÇÃO RENOVATÓRIA</h2>\n<p>10.1. Nos termos dos arts. 51 a 57 da Lei nº 8.245/91, fará jus à renovação compulsória do contrato a PARTE LOCATÁRIA que, cumulativamente: (i) explore o imóvel para o mesmo ramo de atividade pelo prazo mínimo e ininterrupto de 3 (três) anos; (ii) tenha contrato escrito e com prazo determinado; e (iii) cujo prazo, somados os contratos consecutivos por escrito, seja de no mínimo 5 (cinco) anos.</p>\n<p>10.2. A ação renovatória deverá ser proposta no interregno de 1 (um) ano, no máximo, até 6 (seis) meses, no mínimo, anteriores à data do término do prazo do contrato em vigor, sob pena de decadência do direito.</p>\n\n<h2>11 - CONDIÇÕES GERAIS</h2>\n<p>11.1. Na hipótese de o imóvel sofrer desapropriação, estará o presente contrato rescindido a partir da citação para a ação expropriatória, sendo certo que caberá à PARTE LOCADORA receber o valor da indenização, podendo a PARTE LOCATÁRIA, se assim entender, promover, contra o órgão expropriante, a ação de indenização a que porventura tiver direito.</p>\n<p>11.1.1. A rescisão deste contrato, na hipótese prevista nesta cláusula, não obrigará nenhuma das partes a indenizar a outra.</p>\n<p>11.1.2. Os aluguéis serão contados até a data da efetiva desocupação e entrega das chaves do imóvel à PARTE LOCADORA.</p>\n<p>11.2. Tudo quanto for devido, em razão deste contrato, e que não comporte processo executivo, será cobrado em ação competente, respondendo o devedor, em qualquer hipótese, pelos honorários advocatícios fixados em 20% (vinte por cento) sobre o valor do débito que o credor constituir para o patrocínio dos seus direitos.</p>\n<p>11.3. Obriga-se a PARTE LOCATÁRIA a não praticar e proibir a prática, dentro dos limites do imóvel locado, de atos contrários aos bons costumes, à moral, e a perturbação da vizinhança, além de zelarem e efetuarem as suas expensas, pela manutenção, asseio e conservação das instalações e dependências do imóvel objeto da presente locação, inclusive quanto aos reparos e obras a serem realizadas, oriundas de exigências formuladas pelo Poder Público.</p>\n<p>11.4. A PARTE LOCATÁRIA autoriza proceder sua citação inicial, interpelações, intimações, notificações, ou qualquer outro ato de comunicação processual, mediante correspondência com AR/MP (aviso de recebimento), ou mensagem enviada ao endereço eletrônico indicado no preâmbulo, ou ainda, sendo necessário, pelas demais formas previstas no Código de Processo Civil, em toda e qualquer ação judicial ou procedimento extrajudicial, decorrentes da relação locatícia ora ajustada, especialmente as intimações referidas nos artigos 62, inciso III e 67 incisos II e VII da lei 8.245/91.</p>\n<p>11.5. Quaisquer questões oriundas do presente contrato serão dirimidas no Foro {{#if (existe config.foro_texto)}}da comarca de {{config.foro_texto}}{{else}}da comarca de localização do imóvel{{/if}}, eleito pelas partes como o único competente para tal, com renúncia a qualquer outro, por mais privilegiado que seja ou possa vir a ser.</p>\n\n<p>E por estarem justos e acertados, assinam este instrumento, em 03 (três) vias de igual teor e forma, na presença de duas testemunhas abaixo nomeadas.</p>\n\n<p style=\"margin-top: 24pt;\">{{#if (existe config.municipio_imovel)}}{{config.municipio_imovel}}, {{/if}}{{#if (existe config.data_assinatura)}}{{dataExtenso config.data_assinatura}}{{/if}}.</p>\n\n{{#each locatarios}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{else}}{{this.razao_social}}{{/if}}<br>PARTE LOCATÁRIA</p>\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{this.conjuge.nome}}<br>CÔNJUGE DA PARTE LOCATÁRIA</p>\n{{/if}}{{/if}}\n{{/each}}\n\n{{#each locadores}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{else}}{{this.razao_social}}{{/if}}<br>PARTE LOCADORA</p>\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{this.conjuge.nome}}<br>CÔNJUGE DA PARTE LOCADORA</p>\n{{/if}}{{/if}}\n{{/each}}\n\n{{#if (eq garantia.tipo \"fiador\")}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{#if (eq garantia.fiador.tipo_pessoa \"juridica\")}}{{garantia.fiador.razao_social}}{{else}}{{garantia.fiador.nome}}{{/if}}<br>FIADOR(A)</p>\n{{#if garantia.fiador.conjuge.nome}}{{#if (temConjuge garantia.fiador.estado_civil)}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{garantia.fiador.conjuge.nome}}<br>CÔNJUGE DO(A) FIADOR(A)</p>\n{{/if}}{{/if}}\n{{/if}}\n\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>Nome:<br>CPF:<br>Testemunha</p>\n\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>Nome:<br>CPF:<br>Testemunha</p>\n\n<!-- CLAUSE_SLOT:LOC -->\n\n</div>\n",
  "administracao_locacao_v1.hbs": "<div class=\"contrato\">\n\n<h1>INSTRUMENTO PARTICULAR DE CONTRATO DE ADMINISTRAÇÃO DE LOCAÇÃO DE IMÓVEL</h1>\n\n<p>Pelo presente instrumento particular de contrato de administração de locação, de um lado, como ADMINISTRADORA, {{config.administradora_nome}}{{#if (existe config.administradora_cnpj)}}, pessoa jurídica de direito privado, inscrita no CNPJ/MF sob nº {{cnpj config.administradora_cnpj}}{{/if}}{{#if (existe config.administradora_creci)}}, regularmente inscrita no CRECI sob nº {{config.administradora_creci}}{{/if}}{{#if (existe config.administradora_endereco)}}, com sede na {{config.administradora_endereco}}{{/if}}, e de outro lado, como PROPRIETÁRIO(A) e doravante nomeada PARTE PROPRIETÁRIA, {{#each locadores}}{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{#if (existe this.nacionalidade)}}, {{this.nacionalidade}}{{/if}}{{#if (existe this.estado_civil)}}, {{this.estado_civil}}{{/if}}{{#if (existe this.profissao)}}, {{this.profissao}}{{/if}}{{#if (existe this.rg)}}, portador(a) da cédula de identidade RG nº {{this.rg}}{{/if}}{{#if (existe this.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.cpf}}{{/if}}{{#if (existe this.endereco)}}, residente e domiciliado(a) na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if (existe this.email)}}, endereço eletrônico e-mail {{this.email}}{{/if}}{{else}}{{this.razao_social}}, pessoa jurídica de direito privado, inscrita no CNPJ/MF sob nº {{cnpj this.cnpj}}{{#if (existe this.endereco)}}, com sede na {{this.endereco}}, nº {{this.numero}}{{#if this.complemento}}, {{this.complemento}}{{/if}}{{#if this.bairro}}, {{this.bairro}}{{/if}}{{#if (existe this.cep)}}, CEP {{cep this.cep}}{{/if}}{{#if (existe this.cidade)}}, {{this.cidade}}/{{this.uf}}{{/if}}{{/if}}{{#if this.representante.nome}}, neste ato representada por {{this.representante.nome}}, inscrito(a) no CPF/MF sob nº {{cpf this.representante.cpf}}{{/if}}{{/if}}{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}, casado(a) com {{this.conjuge.nome}}{{#if (existe this.conjuge.cpf)}}, inscrito(a) no CPF/MF sob nº {{cpf this.conjuge.cpf}}{{/if}}{{/if}}{{/if}}{{#unless @last}}; {{/unless}}{{/each}}, têm entre si, justo e acertado o seguinte:</p>\n\n<h2>1. OBJETO</h2>\n<p>1.1. A PARTE PROPRIETÁRIA, proprietária do(a) {{#if (existe imovel.tipo_texto)}}{{imovel.tipo_texto}}{{else}}{{imovel.kind}}{{/if}}{{#if (existe imovel.complemento)}} {{imovel.complemento}}{{/if}}{{#if (existe imovel.condominio_nome)}}, do {{imovel.condominio_nome}}{{/if}}, localizado(a) na {{imovel.rua}}, nº {{imovel.numero}}{{#if imovel.bairro}}, {{imovel.bairro}}{{/if}}{{#if (existe imovel.cep)}}, CEP {{cep imovel.cep}}{{/if}}, {{imovel.cidade}}/{{imovel.uf}}{{#if imovel.inscricao_iptu}}, cadastrado na Prefeitura Municipal de {{imovel.cidade}} pelo contribuinte nº {{imovel.inscricao_iptu}}{{/if}}{{#if imovel.matricula}}, objeto da matrícula nº {{imovel.matricula}}{{#if imovel.cartorio}} do {{imovel.cartorio}}{{/if}}{{/if}}, nomeia e constitui a ADMINISTRADORA para exercer a administração da locação do referido imóvel, nos termos dos artigos 653 a 666 do Código Civil e da Lei nº 8.245/91, mediante as cláusulas e condições seguintes.</p>\n{{#if (gt aluguel.valor 0)}}\n<p>1.2. A locação administrada tem aluguel mensal de referência de {{moeda aluguel.valor}} ({{extenso aluguel.valor}}), sujeito aos reajustes previstos no respectivo contrato de locação.</p>\n{{/if}}\n\n<h2>2. PODERES DA ADMINISTRADORA</h2>\n<p>2.1. Para o desempenho da administração ora contratada, a PARTE PROPRIETÁRIA outorga à ADMINISTRADORA poderes para: (a) cobrar e receber aluguéis, encargos e acessórios da locação, dando recibo e quitação; (b) promover a seleção e a qualificação cadastral de candidatos a locatários, inclusive análise de crédito; (c) firmar, em nome da PARTE PROPRIETÁRIA, recibos, notificações, interpelações e comunicações relativas à locação; (d) acompanhar e realizar vistorias de entrada, periódicas e de saída; (e) contratar, às expensas da PARTE PROPRIETÁRIA e mediante prévia autorização, reparos e serviços de manutenção necessários à conservação do imóvel; (f) reter, dos valores recebidos, a remuneração prevista na cláusula 5ª e os encargos autorizados neste instrumento.</p>\n<p>2.2. Os poderes ora outorgados não compreendem os poderes da cláusula <i>ad judicia</i>; a representação judicial da PARTE PROPRIETÁRIA dependerá de procuração específica outorgada a advogado.</p>\n\n<h2>3. OBRIGAÇÕES DA ADMINISTRADORA</h2>\n<p>3.1. Constituem obrigações da ADMINISTRADORA: (a) empregar, na administração da locação, a diligência habitual do bom administrador (art. 667 do Código Civil, por analogia); (b) repassar à PARTE PROPRIETÁRIA os valores líquidos recebidos, na forma da cláusula 6ª; (c) prestar contas mensalmente, por demonstrativo discriminando valores recebidos, deduções e repasse líquido; (d) comunicar à PARTE PROPRIETÁRIA, em prazo razoável, a inadimplência do locatário e as providências adotadas; (e) zelar pelo cumprimento do contrato de locação pelo locatário, notificando-o das infrações de que tiver conhecimento.</p>\n\n<h2>4. OBRIGAÇÕES DA PARTE PROPRIETÁRIA</h2>\n<p>4.1. Constituem obrigações da PARTE PROPRIETÁRIA: (a) fornecer à ADMINISTRADORA a documentação do imóvel e as informações necessárias à administração da locação; (b) arcar com os encargos que a lei ou o contrato de locação atribuam ao locador, inclusive despesas extraordinárias de condomínio; (c) comunicar previamente à ADMINISTRADORA eventual intenção de alienar o imóvel, observado o direito de preferência do locatário previsto no art. 27 da Lei nº 8.245/91; (d) não receber diretamente do locatário valores relativos à locação administrada sem prévia comunicação à ADMINISTRADORA.</p>\n\n<h2>5. REMUNERAÇÃO</h2>\n<p>5.1. Pela administração ora contratada, a ADMINISTRADORA fará jus à taxa de administração de {{config.taxa_admin_percent}}% ({{numeroExtenso config.taxa_admin_percent}} por cento) sobre os aluguéis e encargos efetivamente recebidos, retida por ocasião de cada repasse.</p>\n{{#if (gt comissao.taxa_locacao_percent 0)}}\n<p>5.2. Pela intermediação da locação inicial, será devida à ADMINISTRADORA, por uma única vez, taxa de locação equivalente a {{comissao.taxa_locacao_percent}}% ({{numeroExtenso comissao.taxa_locacao_percent}} por cento) do primeiro aluguel, retida do primeiro repasse.</p>\n{{/if}}\n\n<h2>6. REPASSE</h2>\n<p>6.1. A ADMINISTRADORA repassará à PARTE PROPRIETÁRIA os valores recebidos do locatário, deduzidas a remuneração prevista na cláusula 5ª e as despesas autorizadas, {{#if (existe config.repasse_texto)}}{{config.repasse_texto}}{{else}}em até 5 (cinco) dias úteis após o efetivo recebimento{{/if}}.</p>\n<p>6.2. O repasse fica condicionado ao efetivo pagamento pelo locatário — a ADMINISTRADORA não responde pela inadimplência do locatário, salvo ajuste expresso em contrário.</p>\n{{#if (eq fiscal.regime_ir \"retem_imobiliaria\")}}\n<p>6.3. A ADMINISTRADORA promoverá a retenção e o recolhimento do Imposto de Renda incidente sobre os aluguéis, na forma da legislação vigente, deduzindo-o do valor repassado e fornecendo à PARTE PROPRIETÁRIA os comprovantes e o informe anual de rendimentos.</p>\n{{else}}\n<p>6.3. O recolhimento do Imposto de Renda incidente sobre os aluguéis (carnê-leão ou apuração própria) é de responsabilidade da PARTE PROPRIETÁRIA, fornecendo a ADMINISTRADORA o demonstrativo anual dos valores repassados.</p>\n{{/if}}\n\n<h2>7. VIGÊNCIA</h2>\n<p>7.1. O presente contrato vigorará enquanto vigorar a locação do imóvel administrado, acompanhando o prazo do respectivo contrato de locação{{#if (existe config.vigencia_inicio_texto)}}, cujo período inicial tem início em {{config.vigencia_inicio_texto}}{{#if (gt aluguel.vigencia_meses 0)}} e prazo de {{aluguel.vigencia_meses}} ({{numeroExtenso aluguel.vigencia_meses}}) meses{{/if}}{{/if}}, e suas prorrogações legais ou convencionais, extinguindo-se automaticamente com o término da locação.</p>\n\n{{#if config.administracao_exclusiva}}\n<h2>8. EXCLUSIVIDADE</h2>\n<p>8.1. A administração ora contratada é exercida em caráter de exclusividade: durante a vigência deste contrato, a PARTE PROPRIETÁRIA não poderá contratar terceiros para administrar a locação do imóvel objeto deste instrumento, nem praticar diretamente os atos de administração aqui delegados sem prévia anuência da ADMINISTRADORA.</p>\n{{/if}}\n\n<h2>9. RESCISÃO</h2>\n<p>9.1. Qualquer das partes poderá denunciar o presente contrato mediante notificação escrita com antecedência mínima de 30 (trinta) dias, sem prejuízo da conclusão dos repasses e da prestação de contas relativos aos valores recebidos até a data da rescisão.</p>\n<p>9.2. A parte que descumprir qualquer das cláusulas do presente contrato ficará sujeita à multa equivalente a 3 (três) vezes a remuneração mensal média percebida pela ADMINISTRADORA nos últimos 12 (doze) meses ou no período de vigência, se menor, sem prejuízo das perdas e danos apuradas.</p>\n\n<h2>10. CONDIÇÕES GERAIS</h2>\n<p>10.1. O presente contrato não estabelece vínculo empregatício ou societário entre as partes, tampouco solidariedade da ADMINISTRADORA pelas obrigações do locatário ou da PARTE PROPRIETÁRIA.</p>\n<p>10.2. As comunicações entre as partes far-se-ão por escrito, admitida a mensagem enviada ao endereço eletrônico indicado no preâmbulo.</p>\n<p>10.3. Quaisquer questões oriundas do presente contrato serão dirimidas no Foro {{#if (existe config.foro_texto)}}da comarca de {{config.foro_texto}}{{else}}da comarca de localização do imóvel{{/if}}, eleito pelas partes como o único competente para tal, com renúncia a qualquer outro, por mais privilegiado que seja ou possa vir a ser.</p>\n\n<p>E por estarem justos e acertados, assinam este instrumento, em 02 (duas) vias de igual teor e forma, na presença de duas testemunhas abaixo nomeadas.</p>\n\n<p style=\"margin-top: 24pt;\">{{#if (existe config.municipio_imovel)}}{{config.municipio_imovel}}, {{/if}}{{#if (existe config.data_assinatura)}}{{dataExtenso config.data_assinatura}}{{/if}}.</p>\n\n{{#each locadores}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{#if (eq this.tipo_pessoa \"fisica\")}}{{this.nome}}{{else}}{{this.razao_social}}{{/if}}<br>PARTE PROPRIETÁRIA</p>\n{{#if this.conjuge.nome}}{{#if (temConjuge this.estado_civil)}}\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{this.conjuge.nome}}<br>CÔNJUGE DA PARTE PROPRIETÁRIA</p>\n{{/if}}{{/if}}\n{{/each}}\n\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>{{config.administradora_nome}}<br>ADMINISTRADORA</p>\n\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>Nome:<br>CPF:<br>Testemunha</p>\n\n<p style=\"margin-top: 36pt; text-align: center;\">____________________________________________<br>Nome:<br>CPF:<br>Testemunha</p>\n\n<!-- CLAUSE_SLOT:ADM_LOC -->\n\n</div>\n",
  "proposta_venda_v1.hbs": "<div style=\"font-family: 'EB Garamond', Georgia, serif; color: #111; max-width: 720px; margin: 0 auto; line-height: 1.5;\">\n  <h1 style=\"text-align: center; font-size: 18pt; margin: 0 0 4px;\">PROPOSTA DE COMPRA</h1>\n  <p style=\"text-align: center; font-size: 10pt; color: #555; margin: 0 0 20px;\">Proposta nº {{numero_proposta}}</p>\n\n  <p>Pela presente, o(a) <strong>PROPONENTE</strong> abaixo qualificado(a) oferece,\n  de forma {{#if via_reduzida}}resumida{{else}}firme{{/if}}, a compra do imóvel a seguir descrito, nas condições aqui declaradas.</p>\n\n  {{#each compradores}}\n  <p><strong>Proponente:</strong> {{this.nome}}{{#if this.cpf}}, CPF {{cpf this.cpf}}{{/if}}{{#if this.email}}, {{this.email}}{{/if}}.</p>\n  {{/each}}\n\n  {{#each imoveis}}\n  <p><strong>Imóvel:</strong> {{this.endereco}}{{#if this.numero}}, nº {{this.numero}}{{/if}}{{#if this.bairro}} — {{this.bairro}}{{/if}}{{#if this.cidade}}, {{this.cidade}}{{#if this.uf}}/{{this.uf}}{{/if}}{{/if}}{{#if this.matricula}}. Matrícula {{this.matricula}}{{/if}}.</p>\n  {{/each}}\n\n  <h2 style=\"font-size: 12pt; margin: 20px 0 8px;\">Condições da oferta</h2>\n  {{#if pagamento.valor_total}}\n  <p><strong>Valor ofertado:</strong> {{moeda pagamento.valor_total}} ({{extenso pagamento.valor_total}}).</p>\n  {{/if}}\n  {{#if pagamento.sinal}}\n  <p><strong>Sinal:</strong> {{moeda pagamento.sinal}}.</p>\n  {{/if}}\n  {{#if pagamento.forma}}\n  <p><strong>Forma de pagamento:</strong> {{pagamento.forma}}.</p>\n  {{/if}}\n  {{#if config.condicoes_internas}}\n  <p><strong>Observações:</strong> {{config.condicoes_internas}}.</p>\n  {{/if}}\n\n  {{#if comissao_incluida}}\n  <h2 style=\"font-size: 12pt; margin: 20px 0 8px;\">Intermediação</h2>\n  <p>A presente negociação é intermediada pela imobiliária, com comissão\n  {{#if comissao.percentual}}de {{numero comissao.percentual}}% sobre o valor da venda{{else}}{{#if comissao.valor}}de {{moeda comissao.valor}}{{/if}}{{/if}}.</p>\n  {{/if}}\n\n  <h2 style=\"font-size: 12pt; margin: 20px 0 8px;\">Validade</h2>\n  <p>Esta proposta é válida até a data indicada no envio, após a qual perde efeito automaticamente, salvo prorrogação expressa.</p>\n\n  {{#if via_reduzida}}\n  <p style=\"margin-top: 24px; font-size: 9pt; color: #555; border-top: 1px solid #ccc; padding-top: 8px;\">\n    Este instrumento reproduz as condições essenciais da Proposta nº {{numero_proposta}},\n    arquivada na íntegra junto à imobiliária.\n  </p>\n  {{/if}}\n\n  <div style=\"margin-top: 40px;\">\n    <p>_______________________________________</p>\n    <p style=\"font-size: 10pt;\">{{#each compradores}}{{this.nome}}{{#unless @last}}; {{/unless}}{{/each}} — Proponente</p>\n  </div>\n  <div style=\"margin-top: 24px;\">\n    <p>_______________________________________</p>\n    <p style=\"font-size: 10pt;\">{{#each vendedores}}{{this.nome}}{{#unless @last}}; {{/unless}}{{/each}} — Vendedor(es)</p>\n  </div>\n</div>\n",
  "proposta_locacao_residencial_v1.hbs": "<div style=\"font-family: 'EB Garamond', Georgia, serif; color: #111; max-width: 720px; margin: 0 auto; line-height: 1.5;\">\n  <h1 style=\"text-align: center; font-size: 18pt; margin: 0 0 4px;\">PROPOSTA DE LOCAÇÃO</h1>\n  <p style=\"text-align: center; font-size: 10pt; color: #555; margin: 0 0 20px;\">Residencial · Proposta nº {{numero_proposta}}</p>\n\n  <p>Pela presente, o(a) <strong>PROPONENTE</strong> abaixo qualificado(a) manifesta\n  interesse em locar o imóvel a seguir descrito, para fim residencial, nas condições declaradas.</p>\n\n  {{#each locatarios}}\n  <p><strong>Proponente (locatário):</strong> {{this.nome}}{{#if this.cpf}}, CPF {{cpf this.cpf}}{{/if}}{{#if this.email}}, {{this.email}}{{/if}}.</p>\n  {{/each}}\n\n  {{#each imoveis}}\n  <p><strong>Imóvel:</strong> {{this.endereco}}{{#if this.numero}}, nº {{this.numero}}{{/if}}{{#if this.bairro}} — {{this.bairro}}{{/if}}{{#if this.cidade}}, {{this.cidade}}{{#if this.uf}}/{{this.uf}}{{/if}}{{/if}}.</p>\n  {{/each}}\n\n  <h2 style=\"font-size: 12pt; margin: 20px 0 8px;\">Condições da oferta</h2>\n  {{#if locacao.valor_aluguel}}\n  <p><strong>Aluguel ofertado:</strong> {{moeda locacao.valor_aluguel}} ({{extenso locacao.valor_aluguel}}) por mês.</p>\n  {{/if}}\n  {{#if locacao.prazo_meses}}\n  <p><strong>Prazo pretendido:</strong> {{locacao.prazo_meses}} meses.</p>\n  {{/if}}\n  {{#if locacao.garantia}}\n  <p><strong>Garantia oferecida:</strong> {{locacao.garantia}}.</p>\n  {{/if}}\n  {{#if locacao.data_entrada}}\n  <p><strong>Início pretendido:</strong> {{dataExtenso locacao.data_entrada}}.</p>\n  {{/if}}\n  {{#if config.condicoes_internas}}\n  <p><strong>Observações:</strong> {{config.condicoes_internas}}.</p>\n  {{/if}}\n\n  {{#if comissao_incluida}}\n  <h2 style=\"font-size: 12pt; margin: 20px 0 8px;\">Intermediação</h2>\n  <p>A presente negociação é intermediada pela imobiliária, com comissão\n  {{#if comissao.percentual}}de {{numero comissao.percentual}}% sobre o valor da locação{{else}}{{#if comissao.valor}}de {{moeda comissao.valor}}{{/if}}{{/if}}.</p>\n  {{/if}}\n\n  <h2 style=\"font-size: 12pt; margin: 20px 0 8px;\">Validade</h2>\n  <p>Esta proposta é válida até a data indicada no envio, após a qual perde efeito automaticamente, salvo prorrogação expressa.</p>\n\n  {{#if via_reduzida}}\n  <p style=\"margin-top: 24px; font-size: 9pt; color: #555; border-top: 1px solid #ccc; padding-top: 8px;\">\n    Este instrumento reproduz as condições essenciais da Proposta nº {{numero_proposta}},\n    arquivada na íntegra junto à imobiliária.\n  </p>\n  {{/if}}\n\n  <div style=\"margin-top: 40px;\">\n    <p>_______________________________________</p>\n    <p style=\"font-size: 10pt;\">{{#each locatarios}}{{this.nome}}{{#unless @last}}; {{/unless}}{{/each}} — Proponente (locatário)</p>\n  </div>\n  <div style=\"margin-top: 24px;\">\n    <p>_______________________________________</p>\n    <p style=\"font-size: 10pt;\">{{#each locadores}}{{this.nome}}{{#unless @last}}; {{/unless}}{{/each}} — Locador(es)</p>\n  </div>\n</div>\n",
  "proposta_locacao_comercial_v1.hbs": "<div style=\"font-family: 'EB Garamond', Georgia, serif; color: #111; max-width: 720px; margin: 0 auto; line-height: 1.5;\">\n  <h1 style=\"text-align: center; font-size: 18pt; margin: 0 0 4px;\">PROPOSTA DE LOCAÇÃO</h1>\n  <p style=\"text-align: center; font-size: 10pt; color: #555; margin: 0 0 20px;\">Comercial · Proposta nº {{numero_proposta}}</p>\n\n  <p>Pela presente, o(a) <strong>PROPONENTE</strong> abaixo qualificado(a) manifesta\n  interesse em locar o imóvel a seguir descrito, para fim não residencial, nas condições declaradas.</p>\n\n  {{#each locatarios}}\n  <p><strong>Proponente (locatário):</strong> {{this.nome}}{{#if this.cpf}}, CPF {{cpf this.cpf}}{{/if}}{{#if this.cnpj}}, CNPJ {{cnpj this.cnpj}}{{/if}}{{#if this.email}}, {{this.email}}{{/if}}.</p>\n  {{/each}}\n\n  {{#each imoveis}}\n  <p><strong>Imóvel:</strong> {{this.endereco}}{{#if this.numero}}, nº {{this.numero}}{{/if}}{{#if this.bairro}} — {{this.bairro}}{{/if}}{{#if this.cidade}}, {{this.cidade}}{{#if this.uf}}/{{this.uf}}{{/if}}{{/if}}.</p>\n  {{/each}}\n\n  <h2 style=\"font-size: 12pt; margin: 20px 0 8px;\">Condições da oferta</h2>\n  {{#if locacao.destinacao}}\n  <p><strong>Destinação / ramo de atividade:</strong> {{locacao.destinacao}}.</p>\n  {{/if}}\n  {{#if locacao.valor_aluguel}}\n  <p><strong>Aluguel ofertado:</strong> {{moeda locacao.valor_aluguel}} ({{extenso locacao.valor_aluguel}}) por mês.</p>\n  {{/if}}\n  {{#if locacao.prazo_meses}}\n  <p><strong>Prazo pretendido:</strong> {{locacao.prazo_meses}} meses.</p>\n  {{/if}}\n  {{#if locacao.garantia}}\n  <p><strong>Garantia oferecida:</strong> {{locacao.garantia}}.</p>\n  {{/if}}\n  {{#if locacao.luvas}}\n  <p><strong>Luvas / ponto:</strong> {{moeda locacao.luvas}}.</p>\n  {{/if}}\n  {{#if locacao.data_entrada}}\n  <p><strong>Início pretendido:</strong> {{dataExtenso locacao.data_entrada}}.</p>\n  {{/if}}\n  {{#if config.condicoes_internas}}\n  <p><strong>Observações:</strong> {{config.condicoes_internas}}.</p>\n  {{/if}}\n\n  {{#if comissao_incluida}}\n  <h2 style=\"font-size: 12pt; margin: 20px 0 8px;\">Intermediação</h2>\n  <p>A presente negociação é intermediada pela imobiliária, com comissão\n  {{#if comissao.percentual}}de {{numero comissao.percentual}}% sobre o valor da locação{{else}}{{#if comissao.valor}}de {{moeda comissao.valor}}{{/if}}{{/if}}.</p>\n  {{/if}}\n\n  <h2 style=\"font-size: 12pt; margin: 20px 0 8px;\">Validade</h2>\n  <p>Esta proposta é válida até a data indicada no envio, após a qual perde efeito automaticamente, salvo prorrogação expressa.</p>\n\n  {{#if via_reduzida}}\n  <p style=\"margin-top: 24px; font-size: 9pt; color: #555; border-top: 1px solid #ccc; padding-top: 8px;\">\n    Este instrumento reproduz as condições essenciais da Proposta nº {{numero_proposta}},\n    arquivada na íntegra junto à imobiliária.\n  </p>\n  {{/if}}\n\n  <div style=\"margin-top: 40px;\">\n    <p>_______________________________________</p>\n    <p style=\"font-size: 10pt;\">{{#each locatarios}}{{this.nome}}{{#unless @last}}; {{/unless}}{{/each}} — Proponente (locatário)</p>\n  </div>\n  <div style=\"margin-top: 24px;\">\n    <p>_______________________________________</p>\n    <p style=\"font-size: 10pt;\">{{#each locadores}}{{this.nome}}{{#unless @last}}; {{/unless}}{{/each}} — Locador(es)</p>\n  </div>\n</div>\n",
};
